quests[2963] = { id = 2963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Omen von Uldum", description = "Seid mir erneut gegrüßt, {name}! Seit Eurer Entdeckung in Uldaman ist die Forscherliga voller Aufregung. Die Liga hat daran gearbeitet, die Geheimnisse der Miniaturplatinscheiben zu enträtseln, die Ihr gefunden habt. Euer treffliches Erscheinen hier in der Halle erlaubt es mir, Euch mitzuteilen, dass wir ziemlich wahrscheinlich eine Spur haben!\n\nHistoriker Karnik hat einige wichtige Hinweise auf den wahren Ursprung des Tals der Behüter in der Wüste von Tanaris gefunden. Er möchte so schnell wie möglich mit Euch sprechen!", sourceObjective = "Sprecht mit Historiker Karnik in der Halle der Forscher in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[2964] = { id = 2964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine zukünftige Aufgabe", description = "Nun, {name}... Wir scheinen derzeit in einer temporären Sackgasse zu stecken. Wir wissen, was wir brauchen - die Platten von Uldum -, aber wir haben keinen Schimmer, wo diese sein könnten. Wir müssen eine Menge Nachforschungen anstellen, um einen guten Einsatzplan zusammenzustellen. Ich habe ein paar Ideen, wo man mit der Suche anfangen könnte. Ich hege große Hoffnungen, dass wir Euch bald bitten werden, loszuziehen und sie zu bergen.\n\nDer Hochforscher muss hiervon in Kenntnis gesetzt werden, {name}. Zweifellos wird er Euch ebenfalls persönlich dafür danken wollen, dass Ihr der Liga wieder einmal geholfen habt.", sourceObjective = "Sprecht mit Hochforscher Magellas in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[2965] = { id = 2965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Omen von Uldum", description = "Ah, {name}, es ist vortrefflich, dass Ihr erneut zu mir gekommen seid. Eure Funde in der Grabungsstätte von Uldaman haben uns Gelehrten sicherlich einigen Gesprächsstoff geliefert. Ich unterhielt mich also gerade mit einer der Druiden, Nara Wildmähne, als mir dämmerte, dass ihre früheren Erfahrungen als Abenteurer von großer Wichtigkeit für unseren nächsten Schritt sein könnten.\n\nIch möchte, dass Ihr mit ihr über ihre Reisen ins Tal der Behüter in der Wüste von Tanaris sprecht. Sie erwartet Euch auf der Anhöhe der Ältesten.", sourceObjective = "Sprecht mit Nara Wildmähne auf der Anhöhe der Ältesten in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[2966] = { id = 2966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mal sehen, was passiert...", description = "Weiser Wahrspruch und ich würden Euch bitten, die Miniaturscheiben, die Ihr gefunden habt, zu den versiegelten Toren von Uldum zu bringen. Wir... wir sind uns nicht ganz sicher, was dann passieren wird.\n\nDas klingt ein wenig riskant, sicher, das geben wir auch zu. Es könnte allerdings auch gar nichts passieren. Vielleicht müsst Ihr die Scheiben mit etwas benutzen. Vielleicht öffnen sich die Türen, wenn Ihr die Scheiben bei Euch habt. Versucht alles Mögliche und seid bereit für alles, was passieren könnte.\n\nFindet alles heraus, was Ihr könnt, und kehrt dann zu mir zurück. Wir werden dann viel zu bereden haben.", sourceObjective = "Bringt die Miniaturplatinscheiben zu den Toren von Uldum in Tanaris und sucht nach Hinweisen auf die Verbindung zwischen beidem.", sourceObjectiveStatus = "unverified-source-field" }
quests[2967] = { id = 2967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Donnerfels", description = "Ihr greift erneut auf das Podest zu und die Platinscheiben erscheinen plötzlich wieder in Eurem Rucksack.\n\nNachdem Ihr das Wissen des Steinbehüters verinnerlicht habt und die Scheiben wieder in Eurem Besitz sind, ist es jetzt an der Zeit, nach Donnerfels zurückzukehren und Nara Wildmähne von Eurer Entdeckung in Kenntnis zu setzen.", sourceObjective = "Sprecht mit Nara Wildmähne in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[2968] = { id = 2968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine zukünftige Aufgabe", description = "Nun, {name}... Wir scheinen unglücklicherweise in einer Sackgasse zu stecken. Wir wissen, was wir brauchen - die Platten von Uldum -, aber wir haben keinen Schimmer, wo diese sein könnten. Wir werden Nachforschungen darüber anstellen und dann einen soliden Einsatzplan entwickeln. Ich habe ein paar Ideen, wo man mit der Suche anfangen könnte; Ich hege große Hoffnungen, dass wir Euch bald bitten werden, Euch wieder unseren Bemühungen um die Entdeckung der Wahrheit anzuschließen.\n\nWeiser Wahrspruch muss hiervon in Kenntnis gesetzt werden, {name}; zweifellos wird er Euch ebenfalls persönlich dafür danken wollen, dass Ihr noch einmal dem Ruf gefolgt seid.", sourceObjective = "Sprecht mit dem Weisen Wahrspruch in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[2969] = { id = 2969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiheit für alle Kreaturen", description = "Der dreckige Grimmtotemklan fängt Feendrachen ein, {name}. Jer'kai und ich haben keine Ahnung, was sie mit ihnen vorhaben, aber es ist bestimmt nichts Gutes.\n\nWir sind nicht stark genug, um uns durch das Lager zu kämpfen und die gefangenen Drachen zu befreien, aber mit Eurer Hilfe...\n\nWenn Ihr willens seid und ein paar starke Freunde habt, dann befreit mit diesem Schlüssel die Kreaturen aus ihrem Käfig und stellt sicher, dass sie mit ihrem Leben davonkommen. Ich werde die ganze Zeit an Eurer Seite sein. Jer'kai wird hier bleiben.", sourceObjective = "Befreit mit dem Bambuskäfigschlüssel die Grimmlingflitzer aus dem Pferch im Grimmtotemlager. Kindal Mondweber sowie mindestens 6 Grimmlingflitzer müssen überleben.\n\nIhr habt 6 Minuten, bis Kindal beschließt, dass es Zeit zum Rückzug und Eure Aufgabe gescheitert ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[2970] = { id = 2970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerechtigkeit üben", description = "Wie sie Euch ja schon mitgeteilt hat, tragen Kindal und ich den Kampf jetzt zu den Grimmtotem. Gemeinsam sollten wir in der Lage sein, einige der Tauren ohne große Gefahr für uns selbst auszuschalten, aber wir würden etwas Hilfe sehr begrüßen, wenn Ihr dazu bereit wärt.\n\nIhr habt das Lager unterhalb von uns ja schon gesehen, aber es gibt mehr davon im Osten. Verwendet Eure eigenen Taktiken, um den Tauren so viel Schaden wie möglich zuzufügen. Wir können uns alle wieder hier treffen, nachdem sie Kindals Pfeile und Eure Waffen geschmeckt haben!", sourceObjective = "Tötet 12 Naturalisten der Grimmtotem, 10 Räuber der Grimmtotem sowie 6 Schamanen der Grimmtotem und kehrt dann zu Jer'kai Mondweber nach Feralas zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[2972] = { id = 2972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerechtigkeit üben", description = "Hier draußen in der Wildnis haben Kindal und ich nur geringe Mittel, um Euch für Eure Hilfe zu entlohnen, aber wir wollen nicht, dass Ihr Euch nicht wertgeschätzt fühlt. Nehmt meinen Siegelring. Solltet Ihr Euch jemals in Teldrassil wiederfinden, geht zum Tempel des Mondes im Herzen von Darnassus. Dort werdet Ihr meine Hohepriesterin vorfinden, Tyrande Wisperwind. Der Ring wird sie wissen lassen, dass es uns gut geht, und Eure Geschichte untermauern.\n\nWir beide danken Euch, {name}.", sourceObjective = "Bringt Jer'kais Siegelring zu Hohepriesterin Tyrande Wisperwind nach Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[2973] = { id = 2973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schimmer für einen neuen Umhang", description = "Grüße, {class}. Ich bin mit meinen Gefährten auf einer Mission für unsere Meister aus Orgrimmar hinunter nach Feralas gereist.\n\nMeine Lebensgefährtin Korrin liebt neue Kleider und daher habe ich vor, ihr einen neuen Umhang zu fertigen, der mit den hauchzarten Flügeln von Feendrachen geschmückt ist. Seid Ihr vielleicht in der Lage, mir zu helfen? Grimmlingflitzer mit prachtvollen Flügeln, wie ich sie will, gibt es westlich vom Camp Mojache.", sourceObjective = "Bringt 10 regenbogenfarbene Grimmlingflitzerflügel zu Krueg Schädelspalter nach Camp Mojache.", sourceObjectiveStatus = "unverified-source-field" }
quests[2974] = { id = 2974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine grausige Entdeckung", description = "Was!? Ihr seid in dieser Gegend auf Tauren getroffen? Ihr macht Witze! Wie sahen sie aus?\n\nDer Grimmtotemklan! Ihr habt einige von denen gefunden? Belgrom, einer unserer Meister, interessiert sich für diese Sippe... Er hat sogar ein Kopfgeld auf sie ausgesetzt.\n\nIhr müsst wieder zurückgehen, {class}. Geht zurück und bringt mir ihre Hörner... haufenweise, wenn Ihr könnt. Mit den Grimmtotem ist nicht zu spaßen und man sollte sie nicht unterschätzen. Geht zurück und erschlagt sie; lasst die Flüsse in Feralas rot werden von ihrem dunklen Blut.", sourceObjective = "Bringt 20 Grimmtotemhörner zu Krueg Schädelspalter in Camp Mojache.", sourceObjectiveStatus = "unverified-source-field" }
quests[2975] = { id = 2975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Oger von Feralas", description = "Der Einfluss des Ogerstamms der Gordunni ist in diesem Gebiet kaum zu übersehen. Schaut Euch mal um, {name}. Seine bloße Anwesenheit zeichnet das Land. Wir müssen die Gordunni zurückdrängen, bevor sie sich in Feralas weiter ausbreiten können.\n\nFolgt dem Fluss nach Norden und Ihr werdet ihren Außenposten finden. Verringert ihre Zahl, {name}. Wir müssen ihnen klar machen, dass Ihresgleichen hier nicht willkommen ist.", sourceObjective = "Rok Orhan im Camp Mojache will, dass Ihr 10 Oger der Gordunni, 10 Magier der Gordunni und 5 Schläger der Gordunni tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[2976] = { id = 2976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine grausige Entdeckung", description = "Was?!\n\nHm, ich hab wohl wirklich ein Kopfgeld erwähnt, nicht wahr? Gut, das wird mich lehren, meinen Mund nicht zu weit aufzureißen, oder?\n\nIhr habt die Arbeit gemacht, also ist es wohl nur gerecht, wenn Ihr den größten Lohn einheimst. Nehmt die Hörner, ich lasse sie für Euch in eine Kiste packen. Findet Belgrom Felshammer im Tal der Ehre. Er wird wissen wollen, was Ihr gesehen habt, und Euch für Eure harte Arbeit belohnen.\n\nMacht es gut, {class}, und danke noch einmal für alles, was Ihr getan habt.", sourceObjective = "Bringt die Kiste mit Grimmtotemhörnern zu Belgrom Felshammer nach Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[2977] = { id = 2977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Eisenschmiede", description = "Ihr greift erneut auf das Podest zu und die Platinscheiben erscheinen plötzlich wieder in Eurem Rucksack.\n\nNachdem Ihr das Wissen des Steinbehüters verinnerlicht habt und die Scheiben wieder in Eurem Besitz sind, ist es jetzt an der Zeit, nach Eisenschmiede zurückzukehren und die Forscherliga von Eurer Entdeckung in Kenntnis zu setzen.", sourceObjective = "Sprecht mit Historiker Karnik in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[2978] = { id = 2978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gordunnischriftrolle", description = "Ihr hebt die verschmutzte Schriftrolle auf und bemerkt, dass sie eine Art Versammlung oder Zeremonie darstellt. Rok Orhan wird sich für diese Schriftrolle, und was sie für die Gordunni bedeutet, interessieren.", sourceObjective = "Bringt die Gordunnischriftrolle zu Rok Orhan ins Camp Mojache.", sourceObjectiveStatus = "unverified-source-field" }
quests[2979] = { id = 2979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Zeremonie", description = "Dies scheinen Pläne für eine Art dunkle Zeremonie zu sein, {name}. Soweit ich das erkennen kann, wird dieses Ritual von den Magierlords der Gordunni ausgeführt.\n\nFindet einen dieser Magierlords und sammelt eine Kugel von ihm.\n\nDie Kugel eines Magiers enthält große Macht und wird uns dabei helfen, mehr über diese Zeremonie und die Magie, die die Gordunni beherrschen, herauszufinden.", sourceObjective = "Rok Orhan im Camp Mojache will, dass Ihr eine Gordunnikugel findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[2980] = { id = 2980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Oger von Feralas", description = "Jetzt, da Ihr bewiesen habt, dass Ihr ein wahrer Kämpfer seid, vertraue ich darauf, dass Ihr den Mut besitzt, mit der vorliegenden Aufgabe weiterzumachen.\n\nReist in die Obere Wildnis südwestlich von hier. Dort gibt es einige verlassene und zerstörte Gebäude auf dem Land, das einst den Nachtelfen gehörte. Sucht nach diesen Ruinen, und wenn Ihr verwelkte Bäume und entweihtes Gelände seht, dann werdet Ihr die Gordunni finden. Drängt sie zurück.\n\nDiese Oger sind viel stärker als diejenigen, denen Ihr bisher entgegengetreten seid, {name}. Seht Euch vor.", sourceObjective = "Rok Orhan im Camp Mojache will, dass Ihr 10 Schamanen der Gordunni, 10 Hexenmeister der Gordunni und 5 Raufer der Gordunni tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[2981] = { id = 2981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Bedrohung in Feralas", description = "Feralas ist der ideale Ort für jemanden mit Eurer Erfahrung, {class}, der sich selbst beweisen will. Ein Stamm von Ogern, die sich Gordunni nennen, ist die vorherrschende Militärmacht dort, und ihre Zahl wächst. Sie müssen aufgehalten werden, bevor sie unsere Anwesenheit in Feralas bedrohen.\n\nEine mir bekannte Kriegerin mit Namen Rok Orhan lebt im Camp Mojache in Feralas; geht zu ihr. Sie wird Euch mehr über die Situation erzählen, wenn Ihr dort ankommt.", sourceObjective = "Belgrom Felshammer will, dass Ihr mit Rok Orhan im Camp Mojache sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[2982] = { id = 2982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Obere Wildnis", description = "Obwohl es gefährlich ist, haben Troyas und ich die Ruinen erforscht, die in den Wäldern von Feralas zu finden sind.\n\nIn jüngster Zeit ist Troyas jedoch oft allein in die Obere Wildnis gegangen und ich mache mir Sorgen um ihn. Die Oger der Gordunni haben dieses Gebiet besetzt und sie reagieren nicht sehr freundlich auf jemanden, der ihr Territorium betritt.\n\nIch hoffte, dass Ihr vielleicht zu den Ruinen im Südosten reisen und einige der Oger beseitigen würdet. Macht es ein wenig sicherer für meinen Troyas und ich werde Euch sehr dankbar sein.", sourceObjective = "Angelas Mondhauch will, dass Ihr 8 Hexenmeister der Gordunni, 8 Schamanen der Gordunni und 8 Schläger der Gordunni tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[2983] = { id = 2983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Es ist eine Weile her, seit Ihr zuletzt geprüft wurdet, {name}. Ihr wart in Euren Studien bisher sehr geduldig, doch es ist an der Zeit, dass Ihr etwas über größere Mächte erlernt... Es ist an der Zeit, dass Ihr wahre Macht erfahrt. Das Element des Feuers ist Euer, wenn Ihr bereit seid, dafür zu bezahlen.\n\nSucht nach Kranal Fiss im Brachland. Er lebt in einer kleinen Siedlung nördlich des Wegekreuzes, aber gebt Acht... wenn Ihr das Land der Nachtelfen erreicht, seid Ihr zu weit gegangen.", sourceObjective = "Sucht Kranal Fiss im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[2984] = { id = 2984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Es ist lange her, seit Ihr zuletzt geprüft wurdet, {name}. Bislang habt Ihr bei Euren Studien Geduld bewiesen, doch die Zeit ist gekommen, da Ihr mehr lernen müsst. Die Zeit ist gekommen, mehr über Zerstörung zu lernen... und über Chaos. Ihr könnt das Element des Feuers verstehen lernen, wenn Ihr bereit seid, dafür zu bezahlen.\n\nSucht nach Kranal Fiss im Brachland. Er lebt in einer kleinen Siedlung nördlich des Wegekreuzes, aber gebt Acht, wenn Ihr das Land der Nachtelfen erreicht, seid Ihr zu weit gegangen.", sourceObjective = "Sucht Kranal Fiss im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[2985] = { id = 2985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Ihr seht aus, als wäret Ihr bereit für die nächste Prüfung, {name}. Ihr wart bislang geduldig in Euren Studien, doch die Zeit ist gekommen, da Ihr mehr erlernen müsst. Die Zeit ist gekommen, mehr über die Reinheit des Wassers zu erlernen.\n\nSucht nach Islen Wasserdeuter im Brachland. Sie befindet sich an der Ostküste, südlich von Ratschet und dem Südstrom. Ihr findet sie in ihrer Angelhütte. Viel Glück, {name}.", sourceObjective = "Sucht Islen Wasserdeuter im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[2986] = { id = 2986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Es ist lange her, seit Ihr zuletzt geprüft wurdet, {name}. Bislang habt Ihr bei Euren Studien Geduld bewiesen, doch die Zeit ist gekommen, da Ihr mehr lernen müsst. Die Zeit ist gekommen, mehr über die Reinheit des Wassers zu lernen.\n\nSucht nach Islen Wasserdeuter im Brachland. Sie befindet sich an der Ostküste, südlich von Ratschet und dem Südstrom. Ihr findet sie in ihrer Fischerhütte. Viel Glück, {name}.", sourceObjective = "Sucht Islen Wasserdeuter im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[2987] = { id = 2987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gordunnikobalt", description = "Ich bin gerade erst hier in Feralas angekommen und habe gehört, dass die Oger der Gordunni, die die Wildnis hier bewohnen, einige interessante Mineralien besitzen. Keiner weiß, was die so vorhaben, aber sie passen höllisch gut auf dieses Zeug auf! Sie lassen es nicht einfach herumliegen. Oh nein, sie vergraben es, damit Leute wie ich es nicht in die Finger bekommen.\n\nWenn Ihr wollt, gebe ich Euch meine Schaufel. Geht zum Außenposten der Gordunni nördlich von hier und grabt mir etwas Gordunnikobalt aus. Haltet nach blauem Glühen Ausschau und fangt dann dort an zu graben!", sourceObjective = "Orwin Gizzmick im Camp Mojache will 12 Proben Gordunnikobalt.", sourceObjectiveStatus = "unverified-source-field" }
quests[2988] = { id = 2988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käfige der Bleichborken", description = "Der Sohn unseres mächtigsten Greifen ist verschwunden! Sturmschwinges Erbe, Scharfschnabel, ging vor ein paar Tagen bei der Jagd mit seinen Eltern verloren und wir glauben, dass die Trolle ihn geschnappt haben.\n\nIhr müsst uns helfen! Durchsucht die Käfige in den beiden Dörfern der Bleichborkentrolle, um herauszufinden, ob Scharfschnabel dort ist.", sourceObjective = "Durchsucht die Käfige in den beiden Dörfern der Bleichborken und kehrt dann zu Greifenmeister Krallenaxt zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[2989] = { id = 2989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Altar von Zul", description = "Scharfschnabel war nicht bei den Bleichborkentrollen. Vielleicht haben ihn die Blutfratzentrolle geholt. Geht zum Altar von Zul am Westrand des Territoriums der Blutfratzen und sucht nach dem Greifenjungen.", sourceObjective = "Überprüft die Oberfläche des Altars von Zul und kehrt dann zu Greifenmeister Krallenaxt zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[2990] = { id = 2990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thadius Grimmschatten", description = "Bringt diese Feder zum Rutengänger Thadius Grimmschatten. Er verließ vor Jahren den Nistgipfel, um sich dunklerem Wissen zuzuwenden, aber in seinem Herzen ist er immer noch ein Wildhammer!\n\nUnd vielleicht können uns seine Talente dabei helfen, Scharfschnabel zu finden.\n\nDiese Feder stammt aus dem Nest, in dem das Greifenjunge schläft. Wenn Ihr sie Thadius gebt, kann er mit etwas Glück seine Rutengangmagie verwenden, um Scharfschnabel zu finden.\n\nViel Glück, {name}. Ihr werdet Thadius in den Verwüsteten Landen finden, im Magierturm der Burg Nethergarde.", sourceObjective = "Bringt Scharfschnabels Feder zu Thadius Grimmschatten in die Verwüsteten Lande.", sourceObjectiveStatus = "unverified-source-field" }
quests[2991] = { id = 2991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nekrums Medaillon", description = "Ich werde herausfinden, wo Euer Greif ist, aber erst müsst Ihr etwas für mich tun. Es gibt da einen Troll in Zul'Farrak, Nekrum der Ausweider, der ein Medaillon besitzt, das ich wirklich gern studieren würde. Bringt mir das Medaillon und ich werde meine Kräfte dafür verwenden, Scharfschnabel zu finden.\n\nZul'Farrak ist jenseits des Ozeans, im Westen, in der Wüste von Tanaris.", sourceObjective = "Bringt Thadius Grimmschatten in den Verwüsteten Landen Nekrums Medaillon.", sourceObjectiveStatus = "unverified-source-field" }
quests[2992] = { id = 2992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Weissagung", description = "Lasst mir etwas Platz, während ich ein Rutengangritual durchführe. Ich werde die Verbindung zwischen der Feder, die Ihr mir gebracht habt, und ihrem Besitzer herstellen und dann selbst dieser Verbindung zu Scharfschnabel folgen.\n\nZumindest... wenn alles nach Plan verläuft. Wenn nicht, nun... dann schließt Ihr besser die Augen.", sourceObjective = "Wartet, bis Grimmschatten das Rutengangritual durchgeführt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[2993] = { id = 2993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr ins Hinterland", description = "Scharfschnabel wird in einem Käfig hoch oben auf einer Klippe am Gipfel des Jintha'Alor im Hinterland gefangen gehalten. Der Schlüssel zu diesem Käfig ist im Besitz der Hohepriesterin der Blutfratzentrolle, der üblen Priesterin Hexx.\n\nDa. Ich habe meinen Teil erfüllt. Ich wünsche Euch Glück, {name}.", sourceObjective = "Sprecht mit Greifenmeister Krallenaxt.", sourceObjectiveStatus = "unverified-source-field" }
quests[2994] = { id = 2994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharfschnabels Rettung", description = "Wir müssen Scharfschnabel retten!\n\nKämpft Euch bis zum Gipfel von Jintha'Alor im Herzen des Blutfratzenterritoriums vor, holt Euch den Schlüssel zu Scharfschnabels Käfig von der üblen Priesterin Hexx und dann sucht und befreit Scharfschnabel.", sourceObjective = "Kämpft Euch bis zum Gipfel von Jintha'Alor durch, tötet die üble Priesterin Hexx, um an den Schlüssel zu Scharfschnabels Käfig zu kommen, und rettet Scharfschnabel.", sourceObjectiveStatus = "unverified-source-field" }
quests[2995] = { id = 2995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachrichtenwege", description = "Die Jagdhütte von Quel'Danil ist ein Zentrum der Kommunikation für die Hochelfen des Hinterlands. Ihre Botschafter sind damit beschäftigt, Beziehungen zu anderen Völkern zu knüpfen, mit denen sie ihr Wissen über die Trolle der Bleichborken teilen, die das Gebiet im südlichen Hinterland bewohnen. Alle Aufzeichnungen betreffs dieses Nachrichtenaustauschs werden in der Hütte aufbewahrt.\n\nWir können es nicht brauchen, wenn die Hochtalelfen Allianzen mit anderen schließen, {name}.\n\nVernichtet die Hochtaldokumente. Wir müssen ihre Nachrichtenwege niederbrennen... im wahrsten Sinne des Wortes.", sourceObjective = "Verbrennt die Hochtalaufzeichnungen, Hochtalberichte und Hochtalnotizen.", sourceObjectiveStatus = "unverified-source-field" }
quests[2996] = { id = 2996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Strahad", description = "Ich habe Euch in der Vergangenheit viele Fertigkeiten beigebracht, aber es ist an der Zeit, dass Euch ein anderer lehrt. Er lebt in Ratschet und sein Name ist Strahad. Er ist ein Mensch, aber lasst Euch deswegen nicht dazu hinreißen, ihn für schwach zu halten. Er mag klein sein, aber er ist auch mächtig. Er kann Euch mächtigere Beschwörungen lehren - ich fühle, dass Ihr dazu bereit seid. Geht nun zu ihm. Er ist in Ratschet... Über der Hafenstadt gleich bei seinem Turm.", sourceObjective = "Sprecht mit Strahad Farsan in Ratschet.", sourceObjectiveStatus = "unverified-source-field" }
quests[2997] = { id = 2997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foliant der Offenbarung", description = "Hallo, {name}. Ich weiß, Ihr seid damit beschäftigt, den Leuten von Dun Morogh zu helfen, aber wenn Ihr etwas Zeit habt, könntet Ihr Euch auf den Weg nach Eisenschmiede hinauf machen, um mit einer unserer am meisten Respektierten zu reden: Tiza Kriegshammer. Zu ihr kommen die jüngeren Paladine, wenn es an der Zeit für sie ist, mehr über das Licht und darüber zu erfahren, was von einem erwartet wird.\n\nIhr könnt sie oben in der Halle der Mysterien finden. Falls Ihr noch nie dort wart, das ist im Mystikerviertel. Viel Glück, {name}.", sourceObjective = "Sprecht mit Tiza Kriegshammer in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[2998] = { id = 2998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foliant der Offenbarung", description = "Seid gegrüßt, <Bruder/Schwester>. Duthorian Rall, einer unserer einflussreichsten Paladine, hat kürzlich von Euch gesprochen. Ich habe mitbekommen, wie er darüber sprach, dass es an der Zeit sei, dass Ihr ein wenig getestet würdet... Dabei fielen auch einige Komplimente darüber, wie gut Ihr bisher abgeschnitten habt.\n\nWenn ich Ihr wäre, würde ich nach Sturmwind gehen und mit ihm sprechen, sobald Ihr Zeit habt. Ich bin sicher, er ist in der Kathedrale des Lichts - dort verbringt er einen Großteil seiner Zeit.", sourceObjective = "Sprecht mit Duthorian Rall in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[2999] = { id = 2999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foliant der Offenbarung", description = "Hallo, {name}. Ich weiß, Ihr seid damit beschäftigt, den Leuten von Dun Morogh zu helfen, aber wenn Ihr etwas Zeit habt, könntet Ihr nach oben gehen, um mit einer unserer am meisten Respektierten zu reden: Tiza Kriegshammer. Zu ihr kommen die jüngeren Paladine, wenn es an der Zeit für sie ist, mehr über das Licht und darüber zu erfahren, was von einem erwartet wird.", sourceObjective = "Sprecht mit Tiza Kriegshammer in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[3000] = { id = 3000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foliant der Offenbarung", description = "Hallo, {name}. Ich weiß, Ihr seid damit beschäftigt, den Völkern Azeroths zu helfen, aber wenn Ihr etwas Zeit habt, solltet Ihr nach Eisenschmiede zurückkehren, um mit einem der am meisten respektierten Paladine Eurer Heimat zu reden: Tiza Kriegshammer. Zu ihr kommen die jüngeren Zwergenpaladine, wenn es an der Zeit für sie ist, mehr über das Licht und darüber zu erfahren, was von uns allen erwartet wird.\n\nIhr findet sie im Obergeschoss der Halle der Mysterien, die sich im Mystikerviertel befindet.", sourceObjective = "Sprecht mit Tiza Kriegshammer in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[3001] = { id = 3001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Strahad", description = "Ich habe Euch in der Vergangenheit viele Fertigkeiten beigebracht, aber es ist an der Zeit, dass Euch ein anderer lehrt. Er lebt in Ratschet und sein Name ist Strahad. Er ist ein Mensch, aber lasst Euch deswegen nicht dazu hinreißen, ihn für schwach zu halten oder als Euren Feind anzusehen - zumindest vorerst. Er ist mächtig und sollte respektiert werden. Er kann Euch große Beschwörungen lehren, Beschwörungen, für die Ihr, glaube ich, bereit seid. Geht nun zu ihm.\n\nEr ist in Ratschet... Über der Hafenstadt, gleich bei dem Turm dort.", sourceObjective = "Findet Strahad Farsan in Ratschet.", sourceObjectiveStatus = "unverified-source-field" }
quests[3002] = { id = 3002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gordunnikugel", description = "Obwohl ich meinen Feind genau kenne, bin ich ein Krieger, {name}. Ich kann Euch nicht sagen, über welche Fähigkeiten diese Kugel verfügt.\n\nIch kenne einen Magier in Orgrimmar, der uns mehr über die Kugel sagen können wird. Bringt sie zu ihm.", sourceObjective = "Bringt die Gordunnikugel zu Uthel'nay in die Dunkeldornenlodge in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[3022] = { id = 3022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsichtig behandeln", description = "{name}, ich sehe deutlich, dass Ihr Euch liebend gern meiner noblen Sache zuwenden möchtet. Ja, natürlich könnt Ihr etwas für mich tun!\n\nBringt diese Kiste mit Eiern zu Erelas Himmelsbern. Das ist ein Druide, der sich um diese Eier kümmert. Er bebrütet sie und bildet dann die jungen Hippogryphen aus. Ihr findet ihn in Teldrassil, in einem kleinen Dorf im Süden namens Rut'theran.", sourceObjective = "Bringt die sorgfältig verpackte Kiste zu Erelas Himmelsbern in das Dorf Rut'theran.", sourceObjectiveStatus = "unverified-source-field" }
quests[3042] = { id = 3042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trollaushärter", description = "Die Trolle der Sandwüter von Zul'Farrak stellen ein Aushärtungsmittel aus Sandstein her, und ich kann dies verwenden, um die von mir hergestellten Waren auszuhärten, ja, so ist es! Von Kennern wird es hoch gepriesen; wenn Ihr mir also einen guten Vorrat dieses Härters bringt, werde ich Euch reich belohnen.\n\nZul'Farrak liegt nordwestlich von Gadgetzan. Viel Glück.", sourceObjective = "Bringt 20 Phiolen Trollaushärter zu Trenton Lichthammer in Gadgetzan.", sourceObjectiveStatus = "unverified-source-field" }
quests[3062] = { id = 3062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkles Herz", description = "Edana Hasskralle ist die Königin der Nordschwingen, die in den Ruinen im Westen zu Hause sind. Sie ist das vollkommen Böse; ich habe gehört, dass sie ein Herz aus Kristall hat. Sie ist bar jeglicher Emotionen außer dem Hass, den sie für alle anderen fühlt. Ihr müsst Euch Edana stellen und mir ihr dunkles Herz zurückbringen.\n\nIch habe von einem Horn gehört, das die Harpyien tragen - wenn es bei den Hasskrallensteinen, im nördlichen Teil der Ruinen, geblasen wird, wird die Königin beschworen.\n\nStellt Euch ihre Überraschung vor, wenn es nicht die ihren sind, die auf sie warten, sondern ihr Tod.", sourceObjective = "Talo Dornhuf im Camp Mojache will das dunkle Herz von Edana Hasskralle.", sourceObjectiveStatus = "unverified-source-field" }
quests[3063] = { id = 3063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache an den Nordschwingen", description = "Zu meiner Zeit war ich ein erfahrener Jäger. Es gab keine Kreatur, die ich fürchtete. Bis...\n\nIch war draußen im Wald, um nach einem heftigen Kampf meine Klinge zu schärfen, als ich in einen Hinterhalt geriet. Harpyien umzingelten mich, und ich schaffte es kaum, mich in Sicherheit zu bringen.\n\nSelbst heute noch kann ich das Echo ihrer Schreie vernehmen...\n\nDanach war ich nicht mehr derselbe. Aber der Hass kocht in meinem Inneren - ich will Rache, auch noch nach all diesen Jahren.\n\nDie Harpyien der Nordschwingen leben westlich von hier. {name}, rächt mich.", sourceObjective = "Talo Dornhuf möchte, dass Ihr 4 Harpyien der Nordschwingen, 4 Wildfedern der Nordschwingen, 4 Windruferinnen der Nordschwingen und 4 Töter der Nordschwingen erschlagt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3065] = { id = 3065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfache Schrifttafel", description = "Ah, während Ihr fort wart, kam ein Pergament für Euch, {name}.\n\nLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es vom Kriegerlehrer Frang. Er würde gern mit Euch sprechen, wenn Ihr bereit seid. Ihr findet ihn außerhalb des Höhlenbaus, wo er sich in den Schatten verbirgt.", sourceObjective = "Lest die einfache Schrifttafel und sprecht mit Frang im Tal der Prüfungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3082] = { id = 3082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geätzte Schrifttafel", description = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, {name}.\n\nLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie von der Jägerlehrerin Jen'shan. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Jen'shan im Tal der Prüfungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3083] = { id = 3083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlüsselte Schrifttafel", description = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, {name}.\n\nLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie vom Schurkenlehrer Rwag. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.", sourceObjective = "Lest die verschlüsselte Schrifttafel und sprecht mit Rwag im Tal der Prüfungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3084] = { id = 3084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Runen beschriftete Schrifttafel", description = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, {name}.\n\nLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie von der Schamanenlehrerin Shikrik. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Shikrik im Tal der Prüfungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3085] = { id = 3085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheiligte Schrifttafel", description = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, {name}.\n\nLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie vom Priesterlehrer Ken'jai. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.", sourceObjective = "Lest die geheiligte Schrifttafel und sprecht mit Ken'jai außerhalb des Höhlenbaus im Tal der Prüfungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3086] = { id = 3086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyphenschrifttafel", description = "Ah, während Ihr fort wart, kam eine Schrifttafel für Euch, {name}.\n\nLest sie, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam sie von der Magierlehrerin Mai'ah. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", sourceObjective = "Lest die mit Glyphen versehene Schrifttafel und sprecht mit Mai'ah beim Eingang zum Höhlenbau im Tal der Prüfungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3087] = { id = 3087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geätztes Pergament", description = "Ah, während Ihr fort wart, kam ein Pergament für Euch, {name}.\n\nLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es von der Jägerlehrerin Karranisha. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", sourceObjective = "Lest das geätzte Pergament und sprecht mit Karranisha im Tal der Prüfungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3088] = { id = 3088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlüsseltes Pergament", description = "Ah, während Ihr fort wart, kam ein Pergament für Euch, {name}.\n\nLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es vom Schurkenlehrer Rwag. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.", sourceObjective = "Lest das verschlüsselte Pergament und sprecht mit Rwag im Tal der Prüfungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3089] = { id = 3089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Runen beschriftetes Pergament", description = "Ah, während Ihr fort wart, kam ein Pergament für Euch, {name}.\n\nLest es, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es von der Schamanenlehrerin Shikrik. Sie würde gern mit Euch sprechen, wenn Ihr bereit seid.", sourceObjective = "Lest das mit Runen beschriebene Pergament und sprecht mit Shikrik im Tal der Prüfungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3090] = { id = 3090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besudeltes Pergament", description = "Ah, während Ihr fort wart, kam ein Pergament für Euch, {name}.\n\nIch versuche normalerweise, jedweden Kontakt mit Hexenmeistern zu vermeiden, aber ich glaube, Ihr solltet es lesen, wenn Ihr Zeit habt. Wenn ich mich nicht irre, kam es von Eurem neuen Lehrer Nartok. Er würde gern mit Euch sprechen, wenn Ihr bereit seid.", sourceObjective = "Lest das besudelte Pergament und sprecht mit Nartok im Tal der Prüfungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3091] = { id = 3091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfache Notiz", description = "Gerade eben fragte eine Botin nach Euch, {name}. Ich glaube, sie wurde vom Kriegerlehrer Harutt geschickt. Wenn diese Nachricht von Harutt ist, würde ich sie schnellstens lesen.", sourceObjective = "Lest die einfache Nachricht und sprecht mit Harutt Donnerhorn im Camp Narache.", sourceObjectiveStatus = "unverified-source-field" }
quests[3092] = { id = 3092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geätzte Notiz", description = "Gerade eben fragte eine Botin nach Euch, {name}. Ich glaube, sie wurde vom Jägerlehrer Lanka geschickt. Wenn diese Nachricht von Lanka ist, würde ich sie schnellstens lesen.", sourceObjective = "Lest die geätzte Nachricht und sprecht mit Lanka Weitschuss in Camp Narache.", sourceObjectiveStatus = "unverified-source-field" }
quests[3093] = { id = 3093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Runen beschriftete Notiz", description = "Gerade eben fragte eine Botin nach Euch, {name}. Ich glaube, sie wurde von der Schamanenlehrerin Meela geschickt. Wenn diese Nachricht von Meela ist, würde ich sie schnellstens lesen.", sourceObjective = "Lest die mit Runen beschriftete Nachricht und sprecht mit Meela Morgenwandler im Camp Narache.", sourceObjectiveStatus = "unverified-source-field" }
quests[3094] = { id = 3094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefgrüne Notiz", description = "Gerade eben fragte eine Botin nach Euch, {name}. Ich glaube, sie wurde vom Druidenlehrer Gart geschickt. Wenn diese Nachricht von Gart ist, würde ich sie schnellstens lesen.", sourceObjective = "Lest die tiefgrüne Notiz und sprecht mit Gart Nebelläufer im Camp Narache.", sourceObjectiveStatus = "unverified-source-field" }
quests[3095] = { id = 3095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfache Rolle", description = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Kriegerlehrers Dannal zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", sourceObjective = "Lest die einfache Schriftrolle und sprecht mit Dannal Stern in Todesend.", sourceObjectiveStatus = "unverified-source-field" }
quests[3096] = { id = 3096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlüsselte Rolle", description = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Schurkenlehrers David Trias zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", sourceObjective = "Lest die verschlüsselte Schriftrolle und sprecht mit David Trias in Todesend.", sourceObjectiveStatus = "unverified-source-field" }
quests[3097] = { id = 3097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheiligte Rolle", description = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Priesterlehrers Duesten zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", sourceObjective = "Lest die geheiligte Schriftrolle und sprecht mit dem dunklen Kleriker Duesten in der Kirche von Todesend.", sourceObjectiveStatus = "unverified-source-field" }
quests[3098] = { id = 3098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyphenrolle", description = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel der Magierlehrerin Isabella zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", sourceObjective = "Lest die mit Glyphen versehene Schriftrolle und sprecht mit Isabella in der Kirche von Todesend.", sourceObjectiveStatus = "unverified-source-field" }
quests[3099] = { id = 3099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besudelte Rolle", description = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Ich würde meinen, dass es sich um etwas Wichtiges handelt, denn sie scheint das Siegel des Hexenmeisterlehrers Maximillion zu tragen. Ich würde mir die Zeit nehmen, sie zu lesen, bevor ich wieder losziehe.", sourceObjective = "Lest die besudelte Schriftrolle und sprecht mit Maximillion in Todesend.", sourceObjectiveStatus = "unverified-source-field" }
quests[3100] = { id = 3100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfacher Brief", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr mit den Schwarzfelsspionen fertiggeworden seid, {name}. Es scheint sich um einen versiegelten Brief mit den Insignien von Llane, unserem örtlichen Kriegerlehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", sourceObjective = "Lest den einfachen Brief und sprecht mit Llane Beshere in der Abtei von Nordhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[3101] = { id = 3101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geweihter Brief", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr mit den Schwarzfelsspionen fertiggeworden seid, {name}. Es scheint sich um einen versiegelten Brief mit den Insignien von Bruder Sammuel, unserem örtlichen Paladinlehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", sourceObjective = "Lest den geweihten Brief und sprecht mit Bruder Sammuel in der Abtei von Nordhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[3102] = { id = 3102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Encrypted Letter" }
quests[3103] = { id = 3103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheiligter Brief", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr mit den Schwarzfelsspionen fertiggeworden seid, {name}. Es scheint sich um einen versiegelten Brief mit den Insignien von Priesterin Anetta, unserer örtlichen Priesterlehrerin, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", sourceObjective = "Lest den geheiligten Brief und sprecht mit Priesterin Anetta in der Abtei von Nordhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[3104] = { id = 3104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyphenbrief", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr mit den Schwarzfelsspionen fertiggeworden seid, {name}. Es scheint sich um einen versiegelten Brief mit den Insignien von Khelden, unserem örtlichen Magierlehrer, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", sourceObjective = "Lest den mit Glyphen versehenen Brief und sprecht mit Khelden Bremen in der Abtei von Nordhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[3105] = { id = 3105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besudelter Brief", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr mit den Schwarzfelsspionen fertiggeworden seid, {name}. Es scheint sich um einen versiegelten Brief mit den Insignien von Drusilla, einer unserer örtlichen Ausbilderinnen, zu handeln. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", sourceObjective = "Lest den besudelten Brief und sprecht mit Drusilla La Salle nahe der Abtei von Nordhain.", sourceObjectiveStatus = "unverified-source-field" }
quests[3106] = { id = 3106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfache Rune", description = "{name}, diese Rune wurde mir gegeben, damit ich sie an Euch weitergebe. Nehmt Euch einen Moment Zeit, sie zu lesen, wenn Ihr könnt. Ich denke mal, es kommt von dem Kriegerlehrer Thran. Werft doch am besten einen Blick darauf und sucht ihn in Ambossar auf.", sourceObjective = "Lest die einfache Rune und sprecht mit Thran Khorman im Eisklammtal.", sourceObjectiveStatus = "unverified-source-field" }
quests[3107] = { id = 3107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geweihte Rune", description = "{name}, diese Rune wurde mir gegeben, damit ich sie an Euch weitergebe. Nehmt Euch einen Moment Zeit, sie zu lesen, wenn Ihr könnt. Ich denke mal, es kommt von dem Paladinlehrer Bromos. Werft doch am besten ein Blick darauf und sucht ihn in Ambossar auf.", sourceObjective = "Lest die geweihte Rune und sprecht mit Bromos Grummler in Ambossar.", sourceObjectiveStatus = "unverified-source-field" }
quests[3108] = { id = 3108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geätzte Rune", description = "{name}, diese Rune wurde mir gegeben, damit ich sie an Euch weitergebe. Nehmt Euch einen Moment Zeit, sie zu lesen, wenn Ihr könnt. Ich denke mal, es kommt von dem Jägerlehrer Thorgas. Werft doch am besten einen Blick darauf und sucht ihn in Ambossar auf.", sourceObjective = "Lest die geätzte Rune und sprecht mit Thorgas Grimson im Ambossar.", sourceObjectiveStatus = "unverified-source-field" }
quests[3109] = { id = 3109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlüsselte Rune", description = "{name}, diese Rune wurde mir gegeben, damit ich sie an Euch weitergebe. Nehmt Euch einen Moment Zeit, sie zu lesen, wenn Ihr könnt. Ich denke mal, es kommt von dem Schurkenlehrer Solm. Werft doch am besten ein Blick darauf und sucht ihn in Ambossar auf.", sourceObjective = "Lest die verschlüsselte Rune und sprecht mit Solm Hargrin im Ambossar.", sourceObjectiveStatus = "unverified-source-field" }
quests[3110] = { id = 3110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheiligte Rune", description = "{name}, diese Rune wurde mir gegeben, damit ich sie an Euch weitergebe. Nehmt Euch einen Moment Zeit, sie zu lesen, wenn Ihr könnt. Ich denke mal, es kommt von dem Priesterlehrer Branstock. Werft doch am besten ein Blick darauf und sucht ihn in Ambossar auf.", sourceObjective = "Lest die geheiligte Rune und sprecht mit Branstock Khalder in Ambossar.", sourceObjectiveStatus = "unverified-source-field" }
quests[3112] = { id = 3112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfaches Memorandum", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Kriegerlehrer Thran. Werft einen Blick darauf und sucht ihn dann in Ambossar auf, sobald Ihr die Gelegenheit dazu habt.", sourceObjective = "Lest das einfache Memorandum und sprecht mit Thran Khorman im Eisklammtal.", sourceObjectiveStatus = "unverified-source-field" }
quests[3113] = { id = 3113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlüsseltes Memorandum", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Schurkenlehrer Solm. Werft einen Blick darauf und sucht ihn dann in Ambossar auf, sobald Ihr die Gelegenheit dazu habt.", sourceObjective = "Lest das verschlüsselte Memorandum und sprecht mit Solm Hargrin im Eisklammtal.", sourceObjectiveStatus = "unverified-source-field" }
quests[3114] = { id = 3114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glyphenmemorandum", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Magierlehrer Marryk. Werft einen Blick darauf und sucht ihn dann in Ambossar auf, sobald Ihr die Gelegenheit dazu habt.", sourceObjective = "Lest das mit Glyphen versehene Memorandum und sprecht mit Marryk Nurribit in Ambossar oberhalb des Eisklammtals.", sourceObjectiveStatus = "unverified-source-field" }
quests[3115] = { id = 3115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besudelte Rune", description = "Während Ihr unterwegs wart, um mir zu helfen, wurde mir dieses Memorandum für Euch gegeben. Nehmt Euch die Zeit, es zu lesen, wenn Ihr die Gelegenheit dazu habt. Ich glaube, es kommt vom Hexenmeisterlehrerin Saripal. Werft einen Blick darauf und sucht ihn dann in Ambossar auf, sobald Ihr die Gelegenheit dazu habt.\n\nUnd passt auf Euch auf, {name}, man traut Leuten wie Euch hierzulande nicht gerade.", sourceObjective = "Lest die besudelte Rune und sprecht mit Saripal Schmauchbräu in Ambossar oberhalb des Eisklammtals.", sourceObjectiveStatus = "unverified-source-field" }
quests[3116] = { id = 3116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfaches Siegelzeichen", description = "Dieses Siegelzeichen wurde mir durch einen Boten von unserer Kriegerlehrerin Alyissia überreicht. Es sieht so aus, als wollte Alyissia ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.", sourceObjective = "Sprecht mit Alyissia in Aldrassil im Laubschattental.", sourceObjectiveStatus = "unverified-source-field" }
quests[3117] = { id = 3117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geätztes Siegelzeichen", description = "Dieses Siegelzeichen wurde mir durch einen Boten von unserer Jägerlehrerin Ayanna überreicht. Es sieht so aus, als wollte Ayanna ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.", sourceObjective = "Sprecht mit Ayanna Immerlauf in Aldrassil im Laubschattental.", sourceObjectiveStatus = "unverified-source-field" }
quests[3118] = { id = 3118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlüsseltes Siegelzeichen", description = "Dieses Siegelzeichen wurde mir durch einen Boten von unserem Schurkenlehrer Frahun überreicht. Es sieht so aus, als wollte Frahun ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihm.", sourceObjective = "Sprecht mit Frahun Schattenflüsterer in Aldrassil im Laubschattental.", sourceObjectiveStatus = "unverified-source-field" }
quests[3119] = { id = 3119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheiligtes Siegelzeichen", description = "Dieses Siegelzeichen wurde mir durch einen Boten von unserer Priesterlehrerin Shanda überreicht. Es sieht so aus, als wollte Shanda ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.", sourceObjective = "Sprecht mit Shanda in Aldrassil im Laubschattental.", sourceObjectiveStatus = "unverified-source-field" }
quests[3120] = { id = 3120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefgrünes Siegelzeichen", description = "Dieses Siegelzeichen wurde mir durch einen Boten von unserem Druidenlehrer Mardant überreicht. Es sieht so aus, als wollte Mardant ein paar Worte mit Euch wechseln, wenn Ihr einen Moment Zeit habt. Lest es und bringt es dann zu ihm.", sourceObjective = "Sprecht mit Mardant Starkeiche in Aldrassil im Laubschattental.", sourceObjectiveStatus = "unverified-source-field" }
quests[3121] = { id = 3121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine seltsame Bitte", description = "Xerash Feuerklinge am Larisspavillon nördlich von Camp Mojache hat, was ich brauche, um hier beginnen zu können! Er hat ein Gebräu zusammengemischt, das ich für mein... na, Ihr werdet es schon sehen.\n\nAb mit Euch... zu Xerash. Hier, nehmt das mit. Es ist ein Schrumpfkopf, den ich ihm im Tausch für die Kräuter versprochen habe. Es ist der Kopf eines armen Zwergs, der mir im Wald über den Weg gelaufen ist. Ich bin sicher, dass Xerash sehr erfreut sein wird.", sourceObjective = "Bringt den Schrumpfkopf zu Xerash Feuerklinge beim Larisspavillon.", sourceObjectiveStatus = "unverified-source-field" }
quests[3122] = { id = 3122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zu Hexendoktor Uzer'i zurück", description = "Hier sind die Kräuter, {name}. Bringt sie zu Hexendoktor Uzer'i.\n\nUnd sagt ihm, dass ich mit dem Schrumpfkopf sehr zufrieden bin.", sourceObjective = "Bringt Xerashs Kräuterbeutel zu Hexendoktor Uzer'i in Feralas.", sourceObjectiveStatus = "unverified-source-field" }
quests[3123] = { id = 3123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Gefäß wird getestet", description = "Dies ist ein Test, sowohl für das Ritual, das ich durchgeführt habe, als auch für Eure Fähigkeiten. Nehmt dieses Gefäß, {name}. Damit habt Ihr die Macht, eine Kreatur zu schrumpfen und sie darin gefangen zu nehmen.\n\nReist in die Wildnis östlich von hier und haltet nach Bestien Ausschau. Die bösartigen Eisenfellbären und Langzahnläufer sind Eure Ziele, {name}. Tötet sie und benutzt dann das Muisekgefäß, um sie zu schrumpfen und einzufangen, bevor ihr Geist flüchten kann.", sourceObjective = "Tötet 10 Eisenfellbären oder Langzahnläufer und benutzt dann das Gefäß für Bestienmuisek, um die gefallenen Tiere zu schrumpfen und einzufangen.\n\nBringt anschließend 10 Einheiten Bestienmuisek und das Gefäß für Bestienmuisek zu Hexendoktor Uzer'i in Feralas.", sourceObjectiveStatus = "unverified-source-field" }
quests[3124] = { id = 3124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muisek von Hippogryphen", description = "Da Ihr bewiesen habt, dass Ihr vertrauenswürdig und auch in der Lage seid, das Muisekgefäß zu benutzen, möchte ich, dass Ihr eine weitere Kreatur einfangt.\n\nHippogryphen sind seit vielen Jahren die treuen Gefährten der Nachtelfen. Ihre Geister sind loyal und unerschütterlich.\n\nEure Aufgabe besteht darin, 10 Fransenfederhippogryphen auszuschalten, sie schnell zu schrumpfen und mit dem Gefäß einzufangen, sodass ihr Muisek erhalten bleibt. Ihr findet die Hippogryphen in der Oberen Wildnis, südlich von hier.", sourceObjective = "Schaltet 10 Fransenfederhippogryphen eines beliebigen Typs aus und benutzt dann das Muisekgefäß, um sie zu schrumpfen und einzufangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3125] = { id = 3125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muisek von Feendrachen", description = "{name}, als Nächstes müsst Ihr für mich eine Kreatur fangen, die vom Aussehen her sehr zerbrechlich scheint, aber ihr mächtiger Geist ist das, was wir eigentlich besitzen wollen. Die Feendrachen, von denen ich spreche, dienen den Nachtelfen als Verbündete. Wir müssen einen von ihnen einfangen, damit auch die Horde von seiner Geisteskraft profitieren kann.\n\nHier ist das Muisekgefäß, {name}. Schaltet 8 Grimmlingflitzer oder Grimmlingdrachen aus und fangt ihr Muisek ein. Ihr könnt sie westlich von hier finden.", sourceObjective = "Schaltet 8 Grimmlingflitzer oder Grimmlingdrachen aus. Benutzt das Muisekgefäß, um die gefallenen Feendrachen zu schrumpfen und einzufangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3126] = { id = 3126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muisek von Treants", description = "Die umherwandernden Waldgänger, die überall im Wald zu finden sind, sind unser nächstes Ziel, {name}. Nachtelfen haben Treants als Verbündete rekrutiert, um gegen die Horde zu kämpfen. Sie mögen zwar langsam sein, aber als Beschützer sind sie nicht zu unterschätzen.\n\nBald werden wir diese Macht für unsere eigenen Zwecke nutzen können.\n\nFindet 3 umherwandernde Waldgänger, schaltet sie aus und benutzt das Muisekgefäß, um sie zu schrumpfen und einzufangen.", sourceObjective = "Schaltet 3 umherwandernde Waldgänger aus. Benutzt das Muisekgefäß, um die gefallenen Treants zu schrumpfen und einzufangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3127] = { id = 3127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergriesenmuisek", description = "Bei der letzten Aufgabe, die ich Euch stelle, sollt Ihr nach Nordwesten reisen und den letzten Feind finden.\n\nAls die Brennende Legion in der Welt erschien, haben die Bergriesen ihre Berge verlassen, um den Nachtelfen zu helfen. Ihr erkennt sie an ihrer enormen Größe und daran, wie der Boden erzittert, wenn Ihr durch ihr felsiges Gelände reist.\n\nIch kann es kaum erwarten, eine Macht von dieser Größe zu zähmen. Schaltet 7 Bergriesen aus und benutzt dann das Muisekgefäß, um ihr mächtiges Muisek einzufangen.", sourceObjective = "Schaltet 7 Landgänger oder Klippenriesen aus. Benutzt das Muisekgefäß, um die gefallenen Bergriesen zu schrumpfen und einzufangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3128] = { id = 3128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Natürliche Materialien", description = "Ich benötige bestimmte Materialien, um mein Vorhaben zu vervollständigen... Ihr könnt das für mich erledigen, zusammen mit den anderen Aufgaben, die ich Euch stellen werde.\n\nIch brauche einen abgesplitterten Stamm eines Treants aus Feralas. Verkrustete Mineralien könnt Ihr an den Bergriesen und Feendrachen im Westen finden. Sucht mir einige widerstandsfähige Sehnen von den Eulenbestien im Hinterland oder den Hippogryphen von Feralas. Als Letztes benötige ich eine große Menge metallischer Fragmente von einer der Bestien, die ich erwähnt habe.", sourceObjective = "Bringt 2 abgesplitterte Baumstämme, 6 verkrustete Mineralien, 20 Stücke widerstandsfähige Sehne und 40 metallische Fragmente zu Hexendoktor Uzer'i ins Camp Mojache.", sourceObjectiveStatus = "unverified-source-field" }
quests[3129] = { id = 3129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen des Geistes", description = "Es ist ein äußerst komplizierter Vorgang, die Waffen mit dem Muisek zu erfüllen. Aber da ich jetzt sowohl über alle erforderlichen Materialien als auch über das Muisek der von Euch eingefangenen Kreaturen verfüge, kann ich endlich beginnen. Bitte wartet hier, ich werde gleich zurück sein.", sourceObjective = "Hexendoktor Uzer'i will, dass Ihr einen Moment wartet, während er die Waffen vorbereitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[3130] = { id = 3130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen die Hasskämme", description = "Ich werde Euch jetzt zu meinem Stellvertreter Lactronicus schicken. Er hat bisher ein wachsames Auge auf die Nagastreitkräfte gehabt. Ich werde die allgemeine Lage hier in Bezug auf die Naga bewerten. Liebend gern würde ich eine ganze Armee gegen sie aussenden, aber es ist nicht unbedingt ratsam, die Festung einem direkten Angriff der Horde - oder Schlimmerem - schutzlos auszusetzen.\n\nWie dem auch sei, Latronicus erwartet Euch. Gute Arbeit bisher, {name}. Nur weiter so.\n\nIhr könnt wegtreten.", sourceObjective = "Meldet Euch bei Latronicus Mondspeer in der Mondfederfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[3141] = { id = 3141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loramus", description = "Ihr wollt also gegen Dämonen kämpfen? Dann tätet Ihr gut daran, Euch meine Geschichte anzuhören.", sourceObjective = "Lasst Loramus Thalipedes seine Geschichte erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3161] = { id = 3161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gahz'ridian", description = "{name}, ich bin zwar Wissenschaftler, aber im Grunde meines Herzens bin ich auch Schatzsucher!\n\nVor langer Zeit, als Trolle dieses Land besetzt hielten, schufen sie eine große Anzahl von Ornamenten nach dem Vorbild der Gahz'rilla, einer Hydra, die sie als Göttin verehrten. Diese Ornamente werden aus einem Element herausgeschnitzt, das ich nach der Hydragöttin \"Gahz'ridian\" nenne.\n\nIch selbst habe schon einige dieser Ornamente gefunden, aber ich hätte gern noch mehr, um sie zu untersuchen - vielleicht findet Ihr ja noch welche...\n\nIch habe sogar einen Detektor erfunden, der es zu einem Kinderspiel macht, Gahz'ridian zu finden! Legt ihn einfach an und die Suche kann beginnen!", sourceObjective = "Marvon Nietensucher in Tanaris möchte, dass Ihr 30 Ornamente von Gahz'ridian sammelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3181] = { id = 3181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn der Bestie", description = "Das gigantische Horn hat viele Kratzer und Risse. Ein ungewöhnliches Metallobjekt klemmt in der rauen Oberfläche fest.\n\nBeim näheren Hinschauen entdeckt Ihr, dass das Metall in Wirklichkeit ein zerbrochener Axtkopf ist. In das Metall wurden diese Wörter eingeätzt:\n\nEigentum von Gebirgsjägerin Feinkiesel.\n\nAls Ihr versucht, den zerbrochenen Axtkopf herauszuziehen, zerfällt er in unzählige Teile.\n\nUps!", sourceObjective = "Bringt Margols gigantisches Horn zu Gebirgsjägerin Feinkiesel.", sourceObjectiveStatus = "unverified-source-field" }
quests[3182] = { id = 3182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besitznachweis", description = "Ihr erwartet wirklich, dass ich eine solche Geschichte glaube? Wenn es das echte Horn wäre, dann würde meine zerbrochene Axt ja immer noch drinstecken.\n\nHört zu, bringt diese dreiste Fälschung zu Kurator Thorius in Eisenschmiede. Falls er Eure Behauptung bestätigt, werdet Ihr eine Beweisurkunde für Eure Tat erhalten. Bringt mir diesen Beweis und ich werde Euch den Schlüssel für die Sengende Schlucht geben.\n\nGeht schon!", sourceObjective = "Bringt Margols gigantisches Horn zu Kurator Thorius in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[3201] = { id = 3201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich!", description = "Ich kann kaum glauben, dass Feinkiesel die Echtheit des Horns angezweifelt hat. Unter uns, ich denke, sie ist einfach nur eifersüchtig. Ich weiß, dass sie diese Bestie gern selbst getötet hätte, nach dem, was bei dem 'Ereignis' so vorgefallen ist.\n\nIhr braucht also eine Urkunde für Eure Tat? Nachdem Ihr nun gerade dem Museum ein solches Geschenk gemacht habt, sollte das kein Problem sein.\n\n<Kurator Thorius fängt an, ein großes Dokument auszufüllen.>\n\nHier bitte! Das könnt Ihr Feinkiesel zurückbringen.", sourceObjective = "Bringt die Urkunde für die Tat zurück zu Gebirgsjägerin Feinkiesel.", sourceObjectiveStatus = "unverified-source-field" }
quests[3221] = { id = 3221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Renferrel", description = "Während Ihr fort wart, um unseren Todespirschern zu helfen, hat Apotheker Renferrel Euch eine Einladung geschickt. Er hat mir keinerlei Einzelheiten mitgeteilt, aber er wollte mit Euch über die Wolfherzen sprechen, die Ihr ihm gegeben habt.", sourceObjective = "Sprecht mit Apotheker Renferrel in dem Grabmal.", sourceObjectiveStatus = "unverified-source-field" }
quests[3261] = { id = 3261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jorn Himmelsdeuter", description = "Eure Zeit bei mir ist vorbei, {name}. Wenn Ihr mehr lernen wollt, müsst Ihr ins Camp Taurajo gehen und mit Jorn Himmelsdeuter sprechen. Er wird Eure Weiterbildung übernehmen.", sourceObjective = "Sprecht im Camp Taurajo mit Jorn Himmelsdeuter.", sourceObjectiveStatus = "unverified-source-field" }
quests[3281] = { id = 3281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlenes Silber", description = "Ihr habt zwar die Raptoren getötet, aber das Silber, das sie gestohlen haben, muss wiederbeschafft werden! Ich habe Berichte darüber, dass die Raptoren eine große Ansammlung von Nestern südlich von Ratschet haben, Raptorgründe genannt. Es ist sehr wahrscheinlich, dass sie unser gestohlenes Silber dorthin gebracht haben.\n\nGeht zu dieser Raptorzuflucht und haltet nach dem gestohlenen Silber Ausschau. Wenn Ihr es gefunden habt, kommt damit zu mir zurück.", sourceObjective = "Bringt das gestohlene Silber zu Gazrog beim Wegekreuz.", sourceObjectiveStatus = "unverified-source-field" }
quests[3301] = { id = 3301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mura Runentotem", description = "Meine Klangefährtin, Mura Runentotem, ist nach Silberwald gereist, um unseren untoten Verbündeten zu helfen. Der Silberwald ist ein kranker Wald, ein sterbender Wald, und Muras Hoffnung war, ihm neues Leben zu bringen. Vielleicht kann dieses seltsame Leben, das wir im Brachland gefunden haben, ihr bei ihrer Arbeit im Silberwald helfen.\n\nBringt eine Probe der von Euch gesammelten Schalen zu Mura nach Silberwald. Sie hält sich in dem Grabmal auf. Mit etwas Glück vermittelt ihr das Studium der Schalen den Einblick, den sie benötigt, um diesen sterbenden Ort zu heilen.", sourceObjective = "Sprecht mit Mura Runentotem im Grabmal im Silberwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[3321] = { id = 3321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Habt Ihr das verloren?", description = "Ihr habt viel für den Orden getan, {name}. Allein die Hingabe, derer es bedarf, um hierher zu gelangen, hätte jede normale Person abgehalten. Galvan und auch ich haben keinerlei Zweifel, dass Ihr einer von uns seid.\n\nAus diesem Grund denke ich, dass Ihr Euch eine kleine Belohnung verdient habt. Es ist nichts Besonderes, nur eine Kleinigkeit. Vielleicht sind Euch seine Eigenschaften vertraut, denn ich glaube, dass es der Grund war, warum Ihr überhaupt zu uns gekommen seid.", sourceObjective = "Wartet, bis Trenton seine Arbeit erledigt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[3341] = { id = 3341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende bringen", description = "Im Brachland liegt ein schreckliches Dickicht aus ineinander verschlungenen Ranken, Hügel der Klingenhauer genannt. Unsere ersten Beobachtungen haben zwar auf keine große Bedrohung schließen lassen, aber die neuesten Funde geben doch allen Grund zur Sorge...\n\nDie Stacheleber der Hügel der Klingenhauer haben sich mit der Geißel zusammengetan. Ein Lich namens Amnennar der Kältebringer beherrscht sie jetzt und nutzt die Macht seines riesigen Bewusstseins, um jede ihrer Bewegungen zu kontrollieren.\n\nAmnennar verfügt über eine direkte telepathische Verbindung zu Ner'zhul. Diese Bindung müssen wir durchtrennen, {name}. Dem Kältebringer muss ein Ende gemacht werden.", sourceObjective = "Andrew Braunell will, dass Ihr Amnennar den Kältebringer tötet und ihm dessen Schädel bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3361] = { id = 3361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dilemma eines Flüchtlings", description = "Ich war gerade auf dem Weg, zu den anderen Gnomen in Gnomeregan, aber dann ging alles so schrecklich schief!\n\nIch hatte Ambossar mit gepackten Taschen verlassen und stapfte durch hüfthohen Schnee. Dann kam dieses alberne Erdbeben wodurch ich völlig die Orientierung verlor. Letzten Endes bin ich hier gelandet und was noch schlimmer ist, die Trolle haben all mein Zeug gestohlen!\n\n{name}, ich habe mich offensichtlich während der letzten eineinhalb Tage als völlig inkompetent erwiesen. Hättet Ihr etwas dagegen, die Lager der Trolle südwestlich von hier zu infiltrieren und meine Habseligkeiten zurückzubringen?", sourceObjective = "Beschafft Euch Felix' Kasten, Felix' Truhe und Felix' Bolzeneimer.", progress = "Sobald ich mein Werkzeug habe, verschwinde ich hier.", completion = "Hurra, Ihr habt sie gefunden! Macht euch bereit, ihr Frauen von Gnomeregan: hier kommt Felix!\n\nSo, welcher Weg führt von hier weg...", sourceObjectiveStatus = "unverified-source-field" }
quests[3362] = { id = 3362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disteltal", description = "Habt Ihr jemals das Disteltal gesehen? Es ist ein sehr gefährlicher Ort, {name}.\n\nDiesen merkwürdigen Bestien dort traue ich nicht für eine Minute! Ich glaube, man nennt sie knorrige Distelwandler und Distelwurzelformer...\n\nIch möchte in das Tal hinein, aber solange es dort von Distelwandlern wimmelt, kehre ich auf keinen Fall dorthin zurück. Und an dieser Stelle kommt Ihr ins Spiel - wenn Ihr einige von ihnen erledigt, würde ich vielleicht doch dorthin zurückkehren. Was meint Ihr, {name}? Helft Ihr mir?", sourceObjective = "Tran'rek in Gadgetzan möchte, dass Ihr 8 knorrige Distelwandler und 8 Distelwurzelformer erledigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3363] = { id = 3363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Liedblume" }
quests[3364] = { id = 3364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung des kochend heißen Morgengebräus", description = "Bah! Ich sollte dieses köstliche, kochend heiße Morgengebräu schon vor einer ganzen Weile zu Durnan Pelznaht in Ambossar bringen, aber ich musste erst eine Ladung zu Grelin hier bringen. Ich werde es niemals bis nach Ambossar schaffen, bevor das Gebräu kalt wird!\n\nIhr seht hurtig aus. Vielleicht könnt Ihr es schaffen. Diese Tasse wird nur noch fünf Minuten lang heiß bleiben, und Durnan bestellte kein \"eisiges\" Morgengebräu, also beeilt Euch. Ambossar liegt im Nordosten. Es ist eine Siedlung, die in den Berg gebaut wurde.\n\nDanke, {name}, und vergesst nicht, mir meinen Becher zurückzubringen!", sourceObjective = "Bringt ein kochend heißes Morgengebräu zu Durnan Pelznaht in Ambossar hinein, bevor es innerhalb von fünf Minuten kalt wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[3365] = { id = 3365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Becher zurückbringen", description = "Das kam genau zur rechten Zeit! Es geht doch nichts über ein heißes - neee, KOCHEND HEISSES Morgengebräu an einem kalten Wintertag, um einem das Herz zu wärmen.\n\nHier, bitte {name}... seid so nett und bringt für mich den leeren Becher zurück zu Nori, ja?", sourceObjective = "Bringt Nori Stolzmut im Eisklammtal den Becher zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[3366] = { id = 3366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der leuchtende Splitter", description = "Der Splitter ist von einem glänzenden Grün und obwohl er fest ist, scheint etwas wie Rauch genau unterhalb der Oberfläche herumzuwirbeln. Ihr möchtet am liebsten in die Tiefen des Kristalls schauen, aber gleichzeitig wisst Ihr, dass es etwas sehr Beunruhigendes damit auf sich hat.\n\nVielleicht solltet Ihr in Ratschet nach jemandem suchen, der Euch mehr über diesen seltsamen Splitter erzählen kann.", sourceObjective = "Reist nach Ratschet, um die Bedeutung des Alptraumsplitters herauszufinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[3367] = { id = 3367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suntarasteine", description = "<Dorius stöhnt.>\n\nIch bin schwer verletzt, {race}. Fühle mich... benommen... Alles dreht sich... Innere... Blutungen.\n\nIch muss zurück nach Eisenschmiede. Helft mir, {name}.", sourceObjective = "Helft Dorius, zurück nach Eisenschmiede zu kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3368] = { id = 3368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suntarasteine", description = "Bruder,\n\nwenn Du diesen Brief liest, bin ich nicht mehr. Wie er zu dir gelangt, weiß ich nicht, aber danke und belohne denjenigen, der ihn dir bringt.\n\nZu den Steinen: Es gibt sie wirklich und sie befinden sich im Besitz der Dunkeleisenzwerge. Ihr Anführer, Lathoric der Schwarze, benutzt die Kraft der Steine, um mein Ausgrabungsteam zu versklaven. Sie wurden zum Kessel gebracht. Ihre Gedanken wurden verdreht, sie arbeiten Tag und Nacht, um etwas, das Obsidion heißt, zu vollenden.\n\nHilf ihnen, Bruder. Das ist der letzte Wunsch eines toten Mannes.\n\n- Dorius", sourceObjective = "Bringt den angesengten Brief zu Thorius in Eisenschmiede. Er befindet sich in der Halle der Forscher.", sourceObjectiveStatus = "unverified-source-field" }
quests[3369] = { id = 3369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Nightmares" }
quests[3370] = { id = 3370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alptraum", description = "Dieser Splitter trägt große Geheimnisse in sich; es ist die pure Essenz des Smaragdgrünen Traums. Was ich jedoch in diesem Splitter sehe ist kein Traum, diese Art der Vision ist eher ein Alptraum.\n\nIch möchte Euch nicht beunruhigen, {name}, aber ich denke, es ist am besten, wenn Ihr diesen Splitter in die Hände eines weisen Druiden gebt, sobald Ihr könnt...\n\nIhr müsst Mathrengyl Bärenfährte im Zirkel des Cenarius finden. Geht nach Darnassus. Mehr vermag ich Euch nicht zu sagen.", sourceObjective = "Bringt den Alptraumsplitter zu Mathrengyl Bärenfährte in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[3371] = { id = 3371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwergengerechtigkeit", description = "Wo mein Herz einst schlug, ist jetzt ein leeres Loch, {name}. Über den Verlust von Dorius werde ich so schnell nicht hinwegkommen. Ich muss seinen letzten Wunsch erfüllt sehen - diejenigen, die diesen kaltblütigen Mord durchführten, müssen der Gerechtigkeit zugeführt werden.\n\nKehrt zur Sengenden Schlucht zurück und erfüllt seine letzte Bitte. Befreit seine Männer. Die Dunkeleisenzwerge zwingen ihre Sklaven dazu, in den schwelenden Tiefen der Schlackengrube zu arbeiten; einem ausgedehnten Minenkomplex. Sucht dort nach Dorius Männern.", sourceObjective = "Kehrt zur Sengenden Schlucht zurück und sucht Dorius' Archäologenteam.", sourceObjectiveStatus = "unverified-source-field" }
quests[3372] = { id = 3372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erlöst sie", description = "Befreit sie, {race}. Selbst nachdem ihre Körper aufgegeben haben, zwingt die Macht der Suntara sie, ihre Aufgaben weiter zu erfüllen.\n\nDer Altar von Suntara ist der Schlüssel. Geht nach Norden, in die Hügel oberhalb der Höhle... Die Schattenhammerkultisten bewachen dort ein Relikt. Bringt es herbei und stellt es auf den Altar von Suntara.\n\n<Der sterbende Archäologe bricht zusammen.>", sourceObjective = "Sucht das mysteriöse Artefakt, das im nordwestlichen Teil der Sengenden Schlucht von den Zwielichtverehrern bewacht wird und bringt es zum Altar von Suntara in der Schlackengrube.", sourceObjectiveStatus = "unverified-source-field" }
quests[3373] = { id = 3373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Essenz des Eranikus", description = "Als Ihr den Edelstein berührt, ertönt eine tiefe Stimme in Eurem Geist.\n\n\"Sterbliches Wesen, hört diese Bitte. Ich bin Eranikus vom grünen Drachenschwarm, der Hüter dieses verfluchten Tempels. Meine Aufgabe, sicherzustellen, dass die Trolle nie wieder ihre Monstrosität von einem Gott in diese Welt bringen, ist nun fehlgeschlagen. Während ich diesen Edelstein mit einem Teil meiner magischen Essenz fülle, fühle ich, wie mein Traum sich zum Chaos hinbewegt. Ich bitte Euch... legt diesen Edelstein in den Essenzborn in meinem Unterschlupf und lasst unsere Magie dort den Makel von meiner Psyche nehmen, sodass ich endlich ruhen kann.\"", sourceObjective = "Legt die Essenz von Eranikus in den Essenzborn, der sich in dem Versunkenen Tempel in seinem Unterschlupf befindet.", sourceObjectiveStatus = "unverified-source-field" }
quests[3374] = { id = 3374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Essenz des Eranikus", description = "Ihr aktiviert den Schwurstein und Itharius spricht Euren Geist direkt durch den Stein an.\n\n\"Indem Ihr die Ladung dieses Schwursteins angenommen habt, erklärt Ihr Euch einverstanden, meiner Sache und der Sache von Yseras Drachenschwarm behilflich zu sein, und die verderbte Seele von Eranikus zu erlösen. Das erste Opfer, eines von vielen, die Ihr ohne Zweifel bringen müsst, ist, mir den Edelstein zu übergeben, der den Teil von Eranikus' Psyche gefesselt hat, der noch über einen freien Willen verfügt.\"\n\n\"Tut dies, {name}, und wir werden zusammen an der Erlösung einer Seele arbeiten, die es verdient hat, erlöst zu werden.\"", sourceObjective = "Bringt den Schwurstein von Yseras Drachenschwarm sowie die gebundene Essenz des Eranikus zu Itharius in die Sümpfe des Elends. Dort werdet Ihr Eure Entscheidung treffen, ob Ihr Yseras Drachenschwarm helfen wollt oder nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[3375] = { id = 3375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ersatzphiole", description = "Ähm... Ihr braucht eine weitere Wahrsagephiole? Das soll wohl ein Witz sein! Was habt Ihr denn mit der Ersten angestellt?! Wir haben eine Menge Arbeit vor uns, {race}. Diese Phiolen wachsen nun mal nicht auf Bäumen! Eigentlich wünschte ich, es wäre so, dann könnte ich nämlich einfach eine pflücken gehen. Ich habe nämlich keine mehr!\n\nUm Euch eine zu machen, brauch ich Folgendes: Einen Manatrank, ein Stück Kohle und etwas süßen Nektar. Fragt mich ja nicht, warum, bringt mir einfach, was ich brauche, und ich werde Euch eine neue Phiole machen.", sourceObjective = "Bringt einen Manatrank, Kohle und Süßen Nektar zu Talvash del Kissel in Eisenschmiede, um einen Ersatz für Talvashs Wahrsagephiole zu bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3376] = { id = 3376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet Spitzhauer!", description = "{name}... Ihr seid ein Neuling, ich habe von Euch gehört. Vielleicht könnt Ihr uns ja helfen, wo andere bereits versagt haben.\n\nWir Tauren haben in diesem Land unsere Heimstatt geschaffen, aber nicht, ohne teuer dafür zu bezahlen. Die Stacheleber des Borstennackenstamms aus der Dornrankenklamm, mit Häuptling Spitzhauer Dornenmantel als Anführer, machen uns mit ihrem ständigen Krieg das Leben schwer. Ich beauftrage Euch, mir den Kopf des Häuptlings zu bringen!\n\nIhr könnt ihn in der Klamm östlich von hier in dem heruntergekommenen Dorf finden.", sourceObjective = "Bringt den Kopf von Häuptling Spitzhauer Dornenmantel zur Kriegerheldin Windfeder auf der Hochwolkenebene.", sourceObjectiveStatus = "unverified-source-field" }
quests[3377] = { id = 3377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebet an Elune", description = "Werdet Ihr mir helfen, sterbliches Wesen? Hört meine Geschichte.", sourceObjective = "Hört Zamaels Geschichte.", sourceObjectiveStatus = "unverified-source-field" }
quests[3378] = { id = 3378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebet an Elune", description = "Werdet Ihr mir helfen, sterbliches Wesen? Werdet Ihr das Gebet an Elune finden?\n\nWie ich bereits sagte, wurde das Gebet auf eine goldene Schrifttafel geätzt. Einer dieser Götzenanbeter muss sie bei sich tragen.\n\nWenn Ihr mein Gebet wiederfindet, bringt es zu Astarii Sternsucher in Darnassus. Dass mein Glauben nach den zahllosen widerwärtigen Aktionen, die ich gegen diese Welt und seine Einwohner begangen habe, wiederbelebt wurde, ist vollkommen unwichtig, aber mein Gebet muss gehört werden. Absolution ist das Letzte, was ich erwarte.", sourceObjective = "Findet das Gebet an Elune und bringt es zu Astarii Sternsucher in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[3379] = { id = 3379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenweber", description = "Die Spinnen der Sengenden Schlucht sind eine unschätzbare Quelle für Schattenseide. Wie Ihr wisst, ist Schattenseide bei den Fachleuten unseres Gewerbes heiß begehrt.\n\nSeit Kurzem hat sich eine Gruppe von Wilderern in diesem Land eingenistet, die achtlos massenhaft Spinnen töten, ohne darüber nachzudenken, welche Auswirkungen ihre Taten auf Dauer haben können. Die erste Aufgabe, die ich von Euch verlange, ist recht einfach: Findet sie... und macht ihnen ein Ende.\n\nBeginnt Eure Suche im Norden.\n\nWenn Ihr Hilfe benötigt, sprecht mit Schleifer.", sourceObjective = "Tötet die Gruppe der Schattenseidewilderer, die in der Sengenden Schlucht umherstreifen. Nilith hat Grund zu der Annahme, dass es fünf von ihnen gibt, die ausgeschaltet werden müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3380] = { id = 3380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Versunkene Tempel", description = "Es gibt rastlose Geister in dieser Welt, {name}. Es sind Geister, die durch ihre Einsamkeit besudelt wurden und an ein altes Übel gebunden sind...\n\nIch habe von einem Ort gehört, der tief unter der Erdoberfläche liegt... größere Mächte als ich jemals gesehen habe, haben ihn dorthin verbannt.\n\nWenn Ihr mehr über diesen Ort, den Versunkenen Tempel, erfahren wollt, sucht einen Goblin namens Marvon Nietensucher auf. Er hat viele alte Gebiete der Welt erforscht. Zuletzt hieß es, dass er sein Heim in Ratschet verlassen habe, um die Trollruinen von Tanaris zu erforschen.", sourceObjective = "Sucht Marvon Nietensucher in Tanaris.", sourceObjectiveStatus = "unverified-source-field" }
quests[3381] = { id = 3381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Treffen mit dem Meister", description = "Ah, <ein junger/eine junge:r> {race}, <der/die:r> mit Sanath sprechen möchte. Was für ein wundervoller Tag! Ich fühle mich so geehrt, dass Ihr mich mit Eurer Anwesenheit beehrt. Danke!\n\nBitte... seid nicht so arrogant anzunehmen, dass mein Sarkasmus ein Kompliment war. Lasst uns eine Sache klarstellen: Ich mag Euch nicht. Aber diese kleine Unterhaltung hat nichts mit uns zu tun... es geht um meinen Meister.\n\nBringt mir ein Paar Hippogryphenfedern für meine Pfeile und ich werde Euch zu ihm führen. Er bat darum, dass ich ihm Abenteurer schicke, sofern sie sich würdig erweisen.", sourceObjective = "Bringt 2 unbeschädigte Hippogryphenfedern zu Sanath Lim-yo in Azshara, wenn Ihr mit seinem Meister sprechen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3382] = { id = 3382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Mannschaft in Bedrängnis", description = "Wir waren kurz vor der Küste und suchten nach einem sicheren Hafen, um den Anker zu werfen. Die Sonne war noch keine Stunde untergegangen, als sie angriffen... diese verdammten Naga!\n\nIch weiß nicht genau, wonach sie gesucht haben, aber sie haben es offensichtlich nicht gefunden - sie sind bereits schon einmal wiedergekommen. Einige meiner Späher stehen am Eingang zum Tal Wache, um uns zu warnen, wenn der nächste Angriff kommt.\n\nEs tut mir leid, dass Ihr gerade jetzt vorbeikommt, {name}, aber das liegt nicht in meiner Macht.\n\nSeid Ihr bereit für den Kampf Eures Lebens?", sourceObjective = "Verteidigt Kapitän Vanessa Beltis, ihre Mannschaft und die Passagiere der Herrin des Horizonts gegen den Angriff der Naga. Kapitän Vanessa Beltis muss überleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[3385] = { id = 3385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Untermarkt", description = "Sie bezeichnen sich selbst als den Untermarkt: Halsabschneider von Händlern, die verkaufen, verschieben, handeln und zu fast allem bereit sind, vorausgesetzt, der Preis stimmt.\n\nEs kommt noch schlimmer, {name}. Sie haben einen Stützpunkt für ihre Operationen hier in der Sengenden Schlucht errichtet. Handelsmeister Kovic führt diese Operationen an und hat enge Verbindungen zu den Dunkeleisenzwergen des Gebietes.\n\nWir müssen hart zuschlagen und den Anführern ein Zeichen setzen. Erschlagt Handelsmeister Kovic und seinen Diener Clunk. Bringt seinen Händlerranzen zurück, sobald die Tat ausgeführt ist.\n\nZum Kessel!", sourceObjective = "Erschlagt Handelsmeister Kovic und seinen Diener Clunk. Nehmt den Händlerranzen von seinem Leichnam und bringt ihn zu Nilith.", sourceObjectiveStatus = "unverified-source-field" }
quests[3402] = { id = 3402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Untermarkt", description = "Ich will, dass Ihr Vizzklick in Gadgetzan persönlich die Nachricht von Kovics Niederlage überbringt. Ich bin ziemlich sicher, Kovics Tod wird ihn so erfreuen, dass er Euch eine großartige Belohnung geben wird.", sourceObjective = "Sprecht mit Vizzklick in Gadgetzan.", sourceObjectiveStatus = "unverified-source-field" }
quests[3421] = { id = 3421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückreise" }
quests[3441] = { id = 3441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Göttliche Vergeltung", description = "Hört meine Geschichte, Abenteurer.", sourceObjective = "Lasst Kalaran Windklinge seine Geschichte erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3442] = { id = 3442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die fehlerlose Flamme", description = "Ihr habt die richtige Entscheidung getroffen, {name}.\n\nWir müssen dort zuschlagen, wo wir den größten Schaden anrichten: an den vier Wachpostentürmen.\n\nWenn die vier Wachpostentürme in Flammen stehen, starten wir eine Offensive, bevor sie reagieren können.\n\nIhr benötigt das passende Werkzeug, um die Türme in Brand zu setzen. Für die Herstellung des Werkzeugs wird einiges an Materialien benötigt.\n\nBringt mir vier Herzen der Flamme und vier Kugeln Golemöl, und ich werde die Fackel der fehlerlosen Flamme herstellen können.\n\nIhr solltet Euch also zuerst die Golems und Elementare dieses Landes vornehmen.", sourceObjective = "Sammelt 4 Herzen der Flamme und 4 Kugeln Golemöl und bringt die Gegenstände zu Kalaran Windklinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[3443] = { id = 3443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schmieden des Schafts", description = "Um die fehlerlose Flamme halten zu können, brauchen wir noch einen Schaft und eine Ummantelung. Ihr müsst zunächst einen geeigneten Schaft finden.\n\nDie Zuchtmeister und Sklavenhändler der Dunkeleisenzwerge des Kessels benutzen Waffen aus verzaubertem Thorium, eine besonders stabile Legierung. Wenn Ihr mir acht mit Thorium beschichtete Dolche bringen könnt, kann ich die Legierung aufbrechen und einen Schaft schmieden.", sourceObjective = "Bringt 8 mit Thorium beschichtete Dolche zu Kalaran Windklinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[3444] = { id = 3444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der runde Stein", description = "Ich habe einst die furchteinflößenden Kammern des Versunkenen Tempels betreten. Das Böse an jenem Ort durchdringt alle, die eintreten. Mit Mühe und Not habe ich es geschafft, irgendwie meinen Weg wieder nach draußen zu finden, indem ich durch den Schlamm watete, der jetzt den Boden bedeckt. Ich kann mich nur daran erinnern, dass ich durch einen großen, kreisrunden Raum gestolpert bin, der angefüllt war mit Schlangenstatuen...\n\nKürzlich habe ich einen runden Stein entdeckt, der anscheinend das gleiche Schlangensymbol trägt. Ich habe ihn verpackt und in meine Werkstatt nach Ratschet geschickt. Bringt ihn her und ich kann Euch vielleicht mehr erzählen.", sourceObjective = "Holt den runden Stein aus Marvon Nietensuchers Werkstatt in Ratschet.", sourceObjectiveStatus = "unverified-source-field" }
quests[3445] = { id = 3445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Versunkene Tempel", description = "Ich habe von einem Ort gehört, der tief unter der Oberfläche der Erde liegt - dorthin verbannt durch größere Mächte, als ich jemals gesehen habe.\n\nWenn Ihr mehr über diesen Ort, den Versunkenen Tempel, erfahren wollt sucht einen Goblin namens Marvon Nietensucher auf. Genau wie Troyas und ich hat er viele alte Gebiete der Welt erforscht. Zuletzt hieß es, dass er seine Heimstatt in Ratschet verlassen habe, um die Trollruinen von Tanaris zu erforschen.\n\nViel Glück bei Eurer Suche, man hat schon seit längerem nichts mehr von ihm gehört.", sourceObjective = "Sucht Marvon Nietensucher in Tanaris.", sourceObjectiveStatus = "unverified-source-field" }
quests[3446] = { id = 3446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Tiefen", description = "Im Tempel fand ich einen kreisrunden Raum mit sechs Altären, und am Rand eines jeden stand eine Schlangenstatue. Neugierig drückte ich gegen eine von ihnen, um zu sehen, was passieren würde. Es war eine Falle! Durch die Explosion wurde ich fast getötet. Als ich da auf einem Vorsprung lag, sah ich nach unten und bemerkte, dass eine weitere Statue unten im Raum stand; es war ein Altar der Art... Hakkar, ich glaube, so wurde er genannt.\n\nIch denke, dass dieser Altar das Geheimnis ist... Ihr müsst dieses Zeichen zum Altar in den Versunkenen Tempel bringen.", sourceObjective = "Sucht den Altar von Hakkar im Versunkenen Tempel in den Sümpfen des Elends.", sourceObjectiveStatus = "unverified-source-field" }
quests[3447] = { id = 3447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geheimnis des Kreises", description = "Meine Erinnerungen sind verworren, aber ich werde Euch alles sagen, was ich weiß. Der Kreis der Statuen im Versunkenen Tempel mag ja gefährlich sein, ich glaube dennoch, dass sie das Geheimnis eines noch größeren Schatzes in sich bergen.\n\nVom Hauptaltar aus konnte ich eine Reihe von Lichtern aktivieren. Ich glaube, dass Ihr, wenn Ihr die Bedeutung dieser Lichter herausfindet, auch die weiteren Geheimnisse lüften könnt, die sich in diesem Raum verstecken.\n\nAber ich warne Euch, {name}. In dem Tempel ist etwas unermesslich Böses. Es ist anzunehmen, dass alles Wertvolle äußerst streng bewacht wird.", sourceObjective = "Reist zum Versunkenen Tempel und enthüllt das Geheimnis, das sich in dem Kreis der Statuen verbirgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3448] = { id = 3448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bürde weitergeben", description = "Kürzlich erhielt ich den Auftrag, Azshara zu untersuchen, einen einst wunderschönen Landstrich, den die Elfen ihr Zuhause nannten. Das war damals, als sie noch Magie praktizierten. Jetzt ist es dort eher gefährlich als schön, aber das hält uns nicht davon ab, jeden Stein umzudrehen, um Hinweise auf unsere Vergangenheit zu erhalten.\n\nEin Gefährte von mir namens Tymor bot mir seine Hilfe bei der Untersuchung dieses Gebietes an, da er ein besonderes Interesse an solchen Dingen hat.\n\nEr besitzt ein kleines Anwesen rechts neben der Halle der Mysterien hier in der Stadt.", sourceObjective = "Sprecht mit Magier Tymor in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[3449] = { id = 3449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Runen", description = "Einstmals wurde Magie von einigen Elfen genauso verehrt wie Elune selbst. Einige ihrer mächtigsten Magier erstellten Runen und Schrifttafeln, die die Regeln des Arkanen zitierten und Einsichten in ihre Funde gaben. Sie ließen sie an öffentlichen Plätzen aufstellen, damit jeder darüber nachdenken konnte.\n\nIch hätte sehr gern Abpausbilder dieser Runen aus den Ruinen von Eldarath. Ich habe ein Set für Euch, mit dem Ihr Abpausbilder herstellen könnt, aber Ihr müsst sie selbst finden. Seid aber vorsichtig, die Forscherliga ist nicht die Einzige, die sich dafür interessiert.", sourceObjective = "Verwendet das Abschriftenset, um Abpausbilder von der Rune von Beth'Amara, der Rune von Jin'yael, der Rune von Markri und der Rune von Sael'hai herzustellen, bevor Ihr Euch zu der kleinen Insel vor der südlichen Halbinsel von Azshara aufmacht und dem Piloten Xiggs Luntenzünder signalisiert, dass er sie abholen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[3450] = { id = 3450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine einfache Ladung", description = "Ich will diese Abpausbilder sofort in meinen Turm geliefert haben, aber Ihr müsst nicht den ganzen Weg selbst gehen. Ich werde sie einfach per Luftfracht aus Azshara bringen lassen.\n\nXiggs Luntenzünder schuldet mir noch einen oder zwei Gefallen und wird sich bald in der Nähe aufhalten - er wurde zur Küstenpatrouille abkommandiert. Sprecht mit ihm, bevor Ihr weggeht. Er kann Euch eine Leuchtfeuerwaffe geben, damit Ihr ihm signalisieren könnt. Sobald Ihr die Abpausbilder zusammen habt, begebt Euch an den Ort, den er Euch nennt und übergebt sie ihm dann, damit er sie sicher zu meinem Turm bringen kann. Er sollte sich im Hangar im Militärviertel aufhalten.", sourceObjective = "Sprecht mit Xiggs Luntenzünder in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[3451] = { id = 3451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signal zum Abholen", description = "Ah, Tymor hat Euch also geschickt, hm? Ja, dem schulde ich noch einen oder zwei Gefallen. Wie war das? Nein, der kleine Teufel. Ja, da kann ich ihm helfen. Ihr braucht also eine Leuchtfeuerwaffe und einen Ort... nichts leichter als das.\n\nKurz vor der südlichen Halbinsel von Azshara liegt eine kleine Insel, auf der wir eine Landungsplattform gebaut haben. Ihr nehmt diese Leuchtfeuerwaffe und schießt sie dort ab. Ich sehe dann Euer Signal und werde vorbeikommen, um diese... was auch immer er da haben will, mitzunehmen.", sourceObjective = "Sprecht mit Xiggs Luntenzünder in Eisenschmiede und erhaltet von ihm eine Standardleuchtpistole.", sourceObjectiveStatus = "unverified-source-field" }
quests[3452] = { id = 3452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ummantelung der Flamme", description = "Wir brauchen noch ein letztes Teil, um die Fackel zu formen.\n\nIn den Bergen nordwestlich von hier könnt Ihr ein großes Lager des Schattenhammers finden. Es heißt, dass sie Symbole und Götzenbilder zur Verehrung ihres Gottes mit sich herumtragen. Diese Symbole und Götzenbilder besitzen vielleicht genügend Verzauberung, um daraus eine magische Ummantelung herzustellen. Bringt mir ein einziges Symbol von Ragnaros und ich werde versuchen, die Magie aus dem Gegenstand zu extrahieren, um die Ummantelung zu erschaffen.", sourceObjective = "Bringt ein Symbol von Ragnaros zu Kalaran Windklinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[3453] = { id = 3453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Fackel der Vergeltung", description = "Gebt mir einen Augenblick, um die Teile zusammenzufügen und die notwendigen Verzauberungen anzuwenden.", sourceObjective = "Wartet bis Kalaran Windklinge die Fackel der Vergeltung vollendet hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[3454] = { id = 3454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Fackel der Vergeltung", description = "Die Fackel muss jetzt an ihren Besitzer gebunden werden. Nehmt die Fackel auf, {name}.", sourceObjective = "Nehmt die Fackel der Vergeltung.", sourceObjectiveStatus = "unverified-source-field" }
quests[3461] = { id = 3461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Magier Tymor", description = "Tymor hat mir nichts gegeben, um Euch zu bezahlen, also schlage ich vor, dass Ihr das mit ihm besprecht, wenn Ihr zurück in Eisenschmiede seid. Ich bin mir sicher, er wird dann immer noch an seiner Wohnung im Mystikerviertel sein. Klopft einfach bei ihm an, und er soll Euch ja gut bezahlen. Das hier ist nicht gerade ein Spaziergang... das ist schon mal sicher.\n\nDanke nochmals für Eure Hilfe und viel Glück.\n\nOh, das Abschriftenset brauche ich nicht. Warum bringt Ihr es nicht selbst Tymor zurück, wenn Ihr ihn besucht?", sourceObjective = "Bringt Magier Tymors Abschriftenset zu ihm zurück nach Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[3462] = { id = 3462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knappe Malzdarr", description = "Sprecht mit meinem Gesandten, dem Knappen Malzdarr. Er wird Euch weiter unterweisen, wie die Fackel der Vergeltung zu benutzen ist.", sourceObjective = "Sprecht mit dem Knappen Malzdarr.", sourceObjectiveStatus = "unverified-source-field" }
quests[3463] = { id = 3463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt sie in Brand!", description = "Hört gut zu, {name}. Obgleich die vier Türme niemals zerstört werden können, könnt Ihr dennoch die Fackel der Vergeltung benutzen, um sie für lange Zeit in Brand zu setzen. Ein Feuer, das kein Element und keine Macht löschen kann.\n\nWährend sie in Flammen stehen, kann keine Wache oder Wachposteneinheit die Posten besetzen und so ist ihre erste Verteidigungslinie außer Kraft gesetzt.\n\nIhr müsst in jeden Turm eindringen und die Fackel der Vergeltung innerhalb ihrer Befestigung verwenden. Nehmt Euch in Acht vor den Ausgucken der Dunkeleisenzwerge, {name}.", sourceObjective = "Steckt die Wachpostentürme im Norden, Süden, Osten und Westen in Brand, indem Ihr die Fackel der Vergeltung innerhalb der einzelnen Gebäude benutzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3481] = { id = 3481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plunder...", description = "Die Truhe scheint verschlossen zu sein.", sourceObjective = "Öffnet die Truhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[3483] = { id = 3483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signal zum Abholen" }
quests[3501] = { id = 3501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viel hilft viel", description = "Obgleich Ihr wohl niemals eine fehlerlose Draenethystsphäre finden werdet, könnt Ihr zweifelsohne auf Euren Reisen durch dieses Land einige unvollständige Draenethystfragmente entdecken.\n\nEs ist zwar unwahrscheinlich, dass Kum'isha die fehlerhaften Fragmente benutzen kann, um nach Hause zurückzukehren, dennoch können diese Stücke für andere nützliche Zwecke der Draenei dienen.\n\nBringt mir alle fehlerhaften Draenethystfragmente, die Ihr finden könnt, und ich werde Euch belohnen.", sourceObjective = "Bringt Kum'isha unvollständige Draenethystfragmente und Ihr werdet für jedes, das Ihr bringt, belohnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3502] = { id = 3502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des einen Draeneis Plunder...", description = "Nach einer solchen Zurschaustellung von ekelhafter Gier ist mir richtig übel.\n\nWie dem auch sei, ich werde mich nicht allzu lange mit Eurer materiellen Abhängigkeit beschäftigen.\n\nFür jedes unvollständige Draenethystfragment, das Ihr mir bringt, werde ich Euch mit weiterem Plunder belohnen. Mein Haufen Plunder wird kleiner werden, und der Eurige dafür anwachsen. Auf Draeneor nennen wir das eine Situation, bei der alle nur gewinnen können.", sourceObjective = "Bringt Kum'isha unvollständige Draenethystfragmente. Jede Art von Monster in den Verwüsteten Landen könnte ein Fragment bei sich tragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3503] = { id = 3503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffen mit dem Meister" }
quests[3504] = { id = 3504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verraten", description = "Verräterisches, diebisches Weib! So nenne ich sie... und genau das wird sie immer sein!\n\nIch habe wahrscheinlich einen großen Fehler gemacht, {name}. Ich habe einem Blutelfen vertraut. Was schlimmer ist, ich habe einer Frau vertraut!\n\nSie behauptete, in Azshara lägen große Reichtümer... mächtige Gegenstände. Ich sollte ihr nur ein paar Krieger zu ihrem Schutz schicken und dafür würde ich belohnt. Und wer ist jetzt wohl der Dumme - sie hat sie alle umgebracht.\n\nIch will Rache, {name}, aber ich kann es mir nicht leisten, noch jemanden zu schicken. Sucht Ag'tor bei Valormok auf, nördlich des Lagers der Haldarr. Er kann Euch mehr berichten.", sourceObjective = "Bringt den versiegelten Brief zu Ag'tor Blutfaust nach Azshara.", sourceObjectiveStatus = "unverified-source-field" }
quests[3505] = { id = 3505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verraten", description = "Das hatte ich mir gedacht.\n\nWir werden unseren Kreuzzug gegen ihre Tagelöhner entlang der westlichen Steilhänge an der nördlichen Halbinsel von Azshara beginnen. Tötet sie mit blutiger Wut - lasst sie wissen, dass sie die falschen Verbündeten verraten haben.\n\nUm sie selbst müsst Ihr Euch jetzt noch nicht kümmern - sie verbringt die meiste Zeit zusammen mit ihren Leibwachen auf der Suche nach Azshara. Es ist wahrscheinlich am klügsten, erst ihre Tagelöhner zu erschlagen und dann ihr persönliches Lager zu suchen. Es wäre weise auszukundschaften, wo wir sie angreifen können. Vielleicht gibt es ja etwas, womit wir sie provozieren können.", sourceObjective = "Tötet 10 Blutelfeneintreiber und 10 Blutelfenfeldmesser, bevor Ihr Magus Rimtoris Lager sucht. Sobald Ihr es gefunden habt, sucht nach etwas, das für sie von Bedeutung ist und das wir nehmen können, um sie in einen Kampf zu locken.", sourceObjectiveStatus = "unverified-source-field" }
quests[3506] = { id = 3506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verraten", description = "Nach einigen Momenten des Nachdenkens kommt Ihr auf ein paar Ideen, von denen Euch eine zum Lächeln bringt: Vielleicht würde die Zerstörung der Kristalle die Blutelfe ärgern, die für das Abschlachten so vieler Orcs und den Verrat an Belgrom verantwortlich ist?\n\nIhr fahrt fort, mehr vom Manuskript und den Bildern zu entschlüsseln und erkennt, dass einer der Kristalle an den Schöpfer des Kreises gebunden ist - die anderen sind an etwas weitaus Finstereres gebunden.\n\nIhr schließt das Buch und beginnt Euch zu entscheiden, welchen Kristall Ihr zerstören wollt.", sourceObjective = "Zerstört den arkanen Fokussierkristall, der an Magus Rimtori gebunden ist, und tötet sie danach. Bringt dann den Kopf von Magus Rimtori zu Ag'tor Blutfaust nach Azshara.", sourceObjectiveStatus = "unverified-source-field" }
quests[3507] = { id = 3507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verraten", description = "Kehrt zu Belgrom nach Orgrimmar zurück. Er wird ihren Kopf höchstpersönlich sehen wollen. Wir werden in Kürze dorthin zurückkehren.\n\nAh, dies ist heute wahrlich ein Freudentag. Danke für Eure Hilfe, {name}.", sourceObjective = "Sprecht mit Belgrom Felshammer in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[3508] = { id = 3508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Zauberschutz brechen", description = "Ihr seid tollkühn, {name}. Es ist eine bewundernswerte Eigenschaft Eurer Art, sich blind in die Schlacht zu stürzen, auch wenn nur wenig oder gar keine Aussicht auf Erfolg besteht. Ich werde Euch behilflich sein, sei es auch nur, um einen einzigen von Razelikhs Dienern fallen zu sehen.\n\nDen Zauberschutz, der auf Razelikhs Untergebenen liegt, zu brechen, kostet Zeit und macht es nötig, rare Artefakte zu erwerben.\n\nSeid still, ich muss erst das Erleuchtungsritual durchführen. Die Information, die ich dabei erhalte, wird mir helfen, Waffen von großer Macht zu schmieden.", sourceObjective = "Wartet, bis Loramus den Erleuchtungszauber vollendet hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[3509] = { id = 3509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Name der Bestie", description = "Es gibt nur eine Möglichkeit, den Dämonenlord und seine Diener zu verletzen. Eine Waffe der Macht muss geschmiedet werden, die seinen wahren Namen trägt.\n\nWird eine solche Waffe geschmiedet, sind der Dämon und alle, die unter seinem Kommando stehen, verwundbar.\n\nIn Azshara residiert eine geringe Gottheit: Lord Arkkoroc. Ihn müsst Ihr aufsuchen. Aber seid gewarnt - wenn man Euch entdeckt, werden seine Diener alles tun, um Euch zu vernichten.\n\nZweifelsohne müsst Ihr einen Preis für solche Informationen bezahlen.", sourceObjective = "Sprecht mit Lord Arkkoroc in Azshara. Beginnt Eure Suche am Rand des Wassers, um den Tempel von Arkkoran zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[3510] = { id = 3510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Name der Bestie", description = "Sie tötet meine Kinder, sterbliches Wesen. Sie nennt sich selbst die Herrscherin dieser Meere. Eine falsche Göttin, nichts weiter. Zermalmt sie und bringt mir all ihre Köpfe.\n\nDafür erhaltet Ihr den Namen, den Ihr sucht, und etwas anderes von gleicher Bedeutsamkeit.\n\nSie weilt im Gelege... Genannt wird sie Hetaera.\n\n<Lord Arkkoroc zeigt in Richtung Südwesten.>\n\nGeht!", sourceObjective = "Erschlagt Hetaera und bringt den blutigen Kopf Hetaeras, den geschlagenen Kopf Hetaeras und den verwundeten Kopf Hetaeras zu Lord Arkkoroc.", sourceObjectiveStatus = "unverified-source-field" }
quests[3511] = { id = 3511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Name der Bestie", description = "Wie versprochen, werde ich den Namen des Dämonenlords enthüllen: Es ist Razelikh der Entweiher. Zuerst muss ich jedoch etwas vorbereiten, das für Eure Reise von äußerster Wichtigkeit ist.\n\nDie Waffe, die Ihr herstellen wollt, benötigt einen Härter. Gebt mir einen Moment Zeit, um das Blut aus diesen Köpfen herauszupressen.\n\n<Lord Arkkoroc drückt die Köpfe mit seinen gigantischen Fäusten zusammen, sodass das Blut aus ihnen herausfließt.>\n\nBringt diesen Härter zurück zu Loramus, zusammen mit dem Namen der Bestie: Rakh'likh.", sourceObjective = "Bringt den Härter zurück zu Loramus Thalipedes.", sourceObjectiveStatus = "unverified-source-field" }
quests[3512] = { id = 3512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Eranikus' eigenen Worten", description = "{name}, als Erstes werden wir eine Methode ersinnen, um durch den Edelstein mit Eranikus zu sprechen. Zurzeit befindet er sich in einem gefährlichen Zustand zwischen Schlaf und Tod, verstrickt in ein Gewebe aus Alpträumen. Zwar ist die Essenz, die Ihr mir gegeben habt, stark besudelt, aber es gibt dennoch Hoffnung, dass wir zu ihm durchdringen.\n\nReist weit hinaus in das eisige Land des östlichen Winterquell und sucht einen unserer sterblichen Verbündeten, Umbranse den Geistsprecher. Er ist ein menschliches Medium, der für die Toten spricht. Zwar ist Eranikus noch nicht wirklich tot, trotzdem könnte er uns eine Hilfe sein.", sourceObjective = "Reist in den östlichen Teil von Winterquell und sprecht mit Umbranse, dem Geistsprecher.", sourceObjectiveStatus = "unverified-source-field" }
quests[3513] = { id = 3513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die runenverzierte Rolle", description = "Die offiziell aussehende Rolle wurde mit einem silbrigen Band eng verschnürt. Ihr seid Euch sicher, dass jemand das hier sehen möchte, aber wer?\n\nEs gibt einen Außenposten im Norden in der Nähe der Grenze des Eschentals, und wenn die Informationen auf dieser Rolle die Nachtelfen betreffen, dann sollte die Rolle dorthin gebracht werden.", sourceObjective = "Bringt die runenverzierte Rolle zum nördlichen Wachturm des Brachlandes.", sourceObjectiveStatus = "unverified-source-field" }
quests[3514] = { id = 3514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hordenpräsenz", description = "Diese Rolle ist von der Ränke schmiedenden Dryade Rynthariel, Schlüsselmeisterin des Krallenbaus auf dem Steinkrallengipfel.\n\nMit dem Boten, von dem Ihr diese Rolle erbeutet habt, hat sie jetzt ja wohl keinen Kontakt mehr, aber nachgeben dürfen wir trotzdem nicht. Die Horde wird ihre Kundschafter hier nicht tolerieren.\n\n{name}, reist zum Krallenbau. Tötet Rynthariel und stellt ein Symbol auf, das alle sehen können. Nehmt diese Hordenflagge mit Euch, {name}. Hisst sie im Krallenbau, damit sie es sich zweimal überlegen, bevor sie einen weiteren Boten durch unser Gebiet schicken.", sourceObjective = "Tötet die Anführerin des Krallenbaus, Rynthariel die Schlüsselmeisterin.", sourceObjectiveStatus = "unverified-source-field" }
quests[3517] = { id = 3517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen stehlen", description = "Ich muss zugeben, {name}, ich habe das Beste aus meiner Situation in Azshara gemacht. Belgroms Bestrafung hatte schon seine Vorteile.\n\nBevor ich wegging, habe ich einige Nachforschungen angestellt. Ihr wärt überrascht darüber, wie viele wertvolle Gegenstände hier einfach so herumliegen.\n\nIch erzähle Euch noch mehr von meinen Geschäften und gebe Euch sogar einen Anteil an meinen Gewinnen, wenn Ihr mir helft, ein paar von den Sachen einzusammeln.\n\nIn den östlichen Ruinen von Eldarath gibt es Schrifttafeln, die ich benötige. Alle vier wurden nach Hochgeborenenhexern benannt. Bringt sie mir und wir können weiterreden.", sourceObjective = "Sucht die Schrifttafel von Beth'Amara, die Schrifttafel von Jin'yael, die Schrifttafel von Markri und die Schrifttafel von Sael'hai, bevor Ihr zu Jediga in Azshara zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3518] = { id = 3518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung an Magatha", description = "Die erste Schrifttafel geht an einen weiblichen Tauren... mit Namen Magatha. Sie gehört zu den Ältesten in Donnerfels und zu den Befürwortern der Allianz zwischen den Tauren und den Verlassenen. Sie ist mehr als jeder andere der Ältesten der Meinung, dass die Tauren und ihre Lebensart den Verlassenen helfen können, einen Weg zurück zum Menschsein zu finden.\n\nBringt Ihr die Schrifttafel von Beth'Amara. Die Schrifttafel kann das fehlende Glied sein, das sie benötigt, um den Verlassenen zu helfen... das behauptet sie jedenfalls.", sourceObjective = "Bringt die Schrifttafel von Beth'Amara zu Magatha in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[3519] = { id = 3519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Freund in der Not", description = "Aghhh... Ich wurde ziemlich schlimm von einer Spinne namens Githyiss die Üble gebissen, während ich die Spinnenhöhle ganz in ihrer Nähe erforschte. Ich bin sicher, dass ich ernsthaft vergiftet bin; Ihr müsst mir helfen.\n\nSagt es bitte Dirania Silberschein. Sie wird mir helfen können.\n\nBeeilt Euch... Mir ist so schwindelig...", sourceObjective = "Sprecht mit Dirania Silberschein im Laubschattental.", sourceObjectiveStatus = "unverified-source-field" }
quests[3520] = { id = 3520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kreischergeister", description = "Ich suche die Geister der Talkreischer von Feralas. Sie sind die Cousins eines alten, alten Gottes und ihre Geister sind mit ihm verbunden.\n\nNehmt diesen Dornbuschzauberstab und reist nach Feralas. Sucht und besiegt die Talkreischer in Süd- und Mittel-Feralas, und schwingt meinen Dornbuschzauberstab dann über ihre gefallenen Körper. Dadurch wird ihr Geist dazu gebracht, sich zu zeigen. Berührt den Geist und sammelt seine Essenz.\n\nKommt mit meinem Dornbuschzauberstab und der gesammelten Essenz zu mir zurück, und ich werde Euch mehr von dem alten Gott erzählen, von dem ich sprach.", sourceObjective = "Fangt die Geister von 3 Kreischern in Feralas ein und kehrt dann zu Yeh'kinya beim Dampfdruckpier zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[3521] = { id = 3521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iverrons Gegengift", description = "Wir dürften in der Lage sein, Iverron zu helfen, denn ich kenne ein Gegengift, das gegen das Gift wirkt. Bevor ich es herstellen kann, benötige ich allerdings einige Zutaten.\n\nIch brauche Hyazinthpilze. Sie wachsen unter Bäumen. Ihr könnt sie aber auch von den Grells südlich von hier sammeln; sie scheinen sie sehr zu mögen. Außerdem brauche ich noch Mondblütenlilien, die nur an Wasserteichen wachsen.\n\nDie letzte Zutat könnte die Schwierigste sein. Sammelt Waldwebersekret von genau den Spinnen, die Iverron vergiftet haben.", sourceObjective = "Sammelt 7 Hyazinthpilze, 4 Mondblütenlilien und 1 Waldwebersekret.", sourceObjectiveStatus = "unverified-source-field" }
quests[3522] = { id = 3522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iverrons Gegengift", description = "Das Gegengift ist fertig, {name}. Bitte achtet darauf, dass Iverron es auch trinkt.\n\nEs gibt jedoch etwas, das Ihr wissen sollt: Das Gegengift ist nur 5 Minuten wirksam. Ihr müsst es ihm rechtzeitig bringen.\n\nMögen Eure Füße beflügelt sein, {name}.", sourceObjective = "Bringt Iverrons Gegengift zu Iverron, bevor die Zeit um ist. Ihr findet Iverron bei der Höhle im Norden.", sourceObjectiveStatus = "unverified-source-field" }
quests[3523] = { id = 3523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißel der Hügel", description = "Phantastisch! Mein Name ist Belnistrasz und ich danke Euch für meine Rettung. Ich hatte mich schon tot gewähnt... oder schlimmer, als Mahlzeit für dieses von der Geißel befallene Gezücht. Ja, richtig gehört, ich sagte Geißel; sie haben anscheinend mit den Stachelebern hier eine Art Vereinbarung getroffen und dieser Alptraum ist das Ergebnis.\n\nHört mir zu... anstatt einfach wegzulaufen, möchte ich doch uns allen zuliebe versuchen, etwas zu ändern. Könntet Ihr mir dabei helfen? Es ist wahrscheinlich gefährlich, aber Ihr scheint von dem Schlag zu sein, dem das nicht viel ausmacht.", sourceObjective = "Wenn Ihr Belnistrasz helfen wollt, sprecht noch einmal mit ihm und übergebt ihm den Schwurstein, den er Euch gab.", sourceObjectiveStatus = "unverified-source-field" }
quests[3524] = { id = 3524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Land gespült", description = "Majestätische Meereskreaturen begeben sich häufig an die Ufer von Dunkelküste, und liegen dort gestrandet, bis sie sterben. Vor Kurzem wurden diese Kreaturen in immer größerer Zahl an Land gespült. Ich wurde vom Tempel des Mondes zur Untersuchung dorthin geschickt, aber die Anwesenheit der Murlocs entlang des Wassers hat meine Forschungen schwierig gemacht.\n\nEs gibt eine riesige Kreatur, die unmittelbar südlich von Auberdine an Land gespült wurde und die von den widerlichen Grauflossenmurlocs umringt ist. Könntet Ihr Euch dorthin begeben und Knochen von dieser Kreatur für unsere Studien sammeln?", sourceObjective = "Sammelt Meereskreaturknochen von der gestrandeten Meereskreatur unmittelbar südlich von Auberdine und kehrt dann mit ihnen zu Gwennyth Bly'Leggonde nach Auberdine zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[3525] = { id = 3525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausschalten des Götzen", description = "In der Nähe des Eingangs befindet sich ein Götze, der als makabrer Ofen für die Stacheleber fungiert; die Bestien... verzehren die aus dem Brachland Entführten. Ich kann den Götzen außer Funktion setzen und verhindern, dass sie ihn erneut nutzen, aber ich benötige dabei Eure Hilfe. Mein Plan: Begleitet mich zum Götzen. Wenn wir dort angekommen sind, werde ich das Ritual einleiten. Ich werde kaum in der Lage sein, mit Euch zu kommunizieren, geschweige denn, mich zu verteidigen. Schützt mich, während ich den Götzen außer Funktion setze. Wenn sie mich erschlagen, dann ist alles aus.\n\nSteht Ihr mir bei?", sourceObjective = "Begleitet Belnistrasz zum Götzen der Stacheleber in den Hügeln der Klingenhauer.\n\nBeschützt Belnistrasz, während er das Ritual durchführt, um den Götzen auszuschalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[3526] = { id = 3526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gobliningenieurskunst", description = "Bei der Experteningenieurskunst gibt es zwei unterschiedliche Disziplinen: Gnom und Goblin. Natürlich ist die Gobliningenieurskunst die Wahl aller brillanten Ingenieure. Durch den klugen Einsatz von hochempfindlichen Sprengstoffen und phantastischen Ausrüstungsgegenständen lernt Ihr, die Welt zu meistern!\n\n{name}, lest diese Anleitung. Wenn Ihr etwas über Gobliningenieurskunst wissen wollt, dann bringt sie zu Nixx Sprossfeder nach Gadgetzan. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", sourceObjective = "Wenn Ihr etwas über die Gobliningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Nixx Sprossfeder nach Gadgetzan.", sourceObjectiveStatus = "unverified-source-field" }
quests[3527] = { id = 3527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prophezeiung von Mosh'aru", description = "Die alte Prophezeiung von Mosh'aru berichtet von einer Methode, die Essenz des Gottes Hakkar zu bewahren. Sie wurde auf zwei Schrifttafeln niedergeschrieben und zu der Trollstadt Zul'Farrak gebracht, westlich von Gadgetzan.\n\nBringt mir die Schrifttafeln von Mosh'aru!\n\nDie erste Schrifttafel hat der Troll Theka der Märtyrer, der schon lange tot ist. Man sagt, dass seine Verfolger zu Skarabäen verflucht wurden und nun an seinem Schrein herumhuschen.\n\nDie zweite Schrifttafel hat die Hydromantin Velratha, in der Nähe des hochheiligen Teiches von Gahz'rilla.\n\nWenn Ihr die Schrifttafeln habt, bringt sie zu mir.", sourceObjective = "Bringt die erste und die zweite Schrifttafel von Mosh'aru zu Yeh'kinya nach Tanaris.", sourceObjectiveStatus = "unverified-source-field" }
quests[3528] = { id = 3528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gott Hakkar", description = "Jetzt wird es Zeit, die Essenz des Avatars von Hakkar einzufangen.\n\nBringt das Ei von Hakkar in das Sanktum des Gefallenen Gottes im Versunkenen Tempel in Azeroth. Ruft die Macht des Eies an, um den toten Gott aufzuwecken.\n\nEr wird seine Diener gegen Euch ausschicken. Besiegt seine Bluttrinker und nehmt ihr Hakkariblut an Euch; dann benutzt das Blut, um die ewigen Flammen auszulöschen, die Hakkars Geist halten. Erst wenn alle Flammen gelöscht sind, wird der Avatar von Hakkar unsere Welt betreten.\n\nBesiegt ihn und gebt seine Essenz in das Ei von Hakkar.", sourceObjective = "Bringt das gefüllte Ei von Hakkar zu Yeh'kinya nach Tanaris.", sourceObjectiveStatus = "unverified-source-field" }
quests[3541] = { id = 3541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung an Jes'rimon", description = "Ich kenne einen Hehler in Orgrimmar. Er wohnt in der Gasse. Er ist ziemlich schwer zu finden, wenn Ihr nicht wisst, wo Ihr suchen sollt. Wenn Ihr Euch dort in einem der höchsten Gebäude umschaut, solltet Ihr ihn jedoch ohne Probleme finden können.\n\nTut mir aber bitte einen Gefallen und posaunt nicht in ganz Kalimdor herum, dass er dort ist und was er so tut, das wäre schlecht für uns beide.\n\nEr wird uns einen mehr als angemessenen Preis für die Schrifttafel von Jin'yael geben. Ich weiß zwar nicht genau warum, aber Ihr hättet mal sehen sollen, wie aufgeregt er war, als er von ihrem Aufenthaltsort erfahren hat.", sourceObjective = "Bringt die Schrifttafel von Jin'yael zu Jes'rimon nach Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[3542] = { id = 3542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung an Andron Gant", description = "Andron Gant ist mein nächster Kontakt. Normalerweise hält er sich in Unterstadt auf... ganz in der Nähe des Apothekariums.\n\nEr war ein bisschen redselig, als das Gespräch darauf kam, warum er die Schrifttafel haben wollte. Anscheinend wollen einige der Magier von Unterstadt die Arkanzauber studieren, die die Hochgeborenen benutzt haben. Sie glauben, dass ihnen diese Schrifttafel dabei helfen würde. Markri war sehr bewandert im Beschwören von Kreaturen, besonders von Elementaren.\n\nNehmt die Schrifttafel von Markri und kommt zu mir zurück, um Euch Euren Teil der Belohnung abzuholen.", sourceObjective = "Bringt die Schrifttafel von Markri zu Andron Gant nach Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3561] = { id = 3561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung für Erzmagier Xylem", description = "Die letzte Schrifttafel geht an eine sehr gefährliche Person, {name}. Hört auf mich, wenn ich Euch sage, dass ich dieser Person viel weniger traue als irgendeiner der anderen, die Ihr in meinem Namen getroffen habt.\n\nErzmagier Xylem hat einen Turm in den Hügeln mit Ausblick auf ganz Azshara. Er ist zwar ein Mensch, aber er benimmt sich wie kein Mensch, den ich jemals getroffen...oder getötet habe. Er strahlt Macht aus und ich wage nicht, ihn zu fragen, was er mit der Schrifttafel vorhat.\n\nEr kam zu mir, aber er teilte mir mit, dass seine Leibwache Sanath mir helfen würde, zum Turm zu kommen, wenn ich bereit sei, ihn zu treffen. Sucht nach Sanath im Norden.", sourceObjective = "Bringt die Schrifttafel von Sael'hai zu Erzmagier Xylem in Azshara.", sourceObjectiveStatus = "unverified-source-field" }
quests[3562] = { id = 3562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magathas Bezahlung für Jediga", description = "Bringt diese Notiz zu Jediga. Sagt ihr, dass ihre Bezahlung hier auf sie wartet, wenn sie zurückkommt. Und sagt ihr, dass ich mit ihrer Arbeit zufrieden bin.\n\nBeeilt Euch, {name}. Sagt Eurer Meisterin, dass ich hier auf sie warten werde.", sourceObjective = "Bringt Magathas Notiz zu Jediga in Azshara.", sourceObjectiveStatus = "unverified-source-field" }
quests[3563] = { id = 3563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jes'rimons Bezahlung für Jediga", description = "Bringt diesen Brief zu Jediga. Lasst sie wissen, dass unser Handel vorteilhaft ist und ich mit ihrer Arbeit zufrieden bin.\n\nSagt ihr, sie soll schnell nach Orgrimmar zurückkommen und Jes'rimon würde sich gut um sie kümmern.\n\nSagt ihr das und vielleicht benötige ich in Zukunft noch einmal Eure Dienste, {name}.", sourceObjective = "Bringt Jes'rimons Notiz zu Jediga in Azshara.", sourceObjectiveStatus = "unverified-source-field" }
quests[3564] = { id = 3564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Androns Bezahlung für Jediga", description = "Hier... bringt... <hick> das zu Jediga. Viel Glück!", sourceObjective = "Bringt Androns Notiz zu Jediga in Azshara.", sourceObjectiveStatus = "unverified-source-field" }
quests[3565] = { id = 3565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xylems Bezahlung für Jediga", description = "Was ist? Oh, ja, Eure Bezahlung. Natürlich.\n\nNehmt das und fort mit Euch. Jediga wartet bestimmt schon voller Geduld auf Eure Rückkehr.", sourceObjective = "Bringt Xylems Notiz zu Jediga in Azshara.", sourceObjectiveStatus = "unverified-source-field" }
quests[3566] = { id = 3566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erhebt Euch, Obsidion!", description = "Es... Es... Es war alles eine Falle.\n\nVergebt... mir.\n\nTötet den Verräter... Tötet ihn für uns... für Thorius.", sourceObjective = "Tötet Lathoric den Schwarzen und Obsidion. Kehrt zurück zu Thorius nach Eisenschmiede mit dem Kopf von Lathoric dem Schwarzen und dem Herzen von Obsidion.", sourceObjectiveStatus = "unverified-source-field" }
quests[3567] = { id = 3567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An die Spitze" }
quests[3568] = { id = 3568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbreitete Verderbnis", description = "Seht Ihr die Tauren hinter mir - diejenige, die aussieht, als müsste sie sich jeden Moment übergeben? Sie war erst vor Kurzem in Azshara. Sie behauptet, dass sie von einigen Naga verwundet wurde, als sie sich den Weg durch die Ruinen von Eldarath bahnte.\n\nNachdem sie einige von ihnen zurückschlagen konnte, machte sie eine Pause am Strand und trank aus einem der Gezeitenteiche. Jetzt ist ihr ein wenig übel... unter anderem.\n\nIch würde gern herausfinden, was sie getrunken hat. Nehmt diesen Kasten, darin befinden sich einige leere Phiolen, die ich mit Etiketten versehen habe. Füllt jede an einem anderen Teich und kehrt dann zurück.", sourceObjective = "Füllt alle 4 leeren Phiolen an den Gezeitenteichen entlang der Küste der Ruinen von Eldarath in Azshara und kehrt dann zu Chemiker Miesmut zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[3569] = { id = 3569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbreitete Verderbnis", description = "Gebt das Thersa. Vielleicht wird das hier sie heilen... vielleicht aber auch nicht. Wir werden es nicht wissen, solange sie es nicht getrunken hat.", sourceObjective = "Gebt Miesmuts Elixier Thersa Windweise in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3570] = { id = 3570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbreitete Verderbnis" }
quests[3601] = { id = 3601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kim'jael, fürwahr!", description = "Kim'jael, fürwahr! Wisst Ihr, was Kim'jael für die Blutelfen bedeutet, {name}? Kleine Ratte... oder so etwas in der Art. Diese großen Angeber!\n\nSie haben mich angeworben, damit ich ihnen helfe, das Gebiet auszukundschaften und nach einer Art verlorenen Schatz zu suchen. Natürlich habe ich sofort zugegriffen, als sie das Wort 'Schatz' erwähnten und die Summe, die sie mir bezahlen wollten. Aber dann haben sie sich gegen mich gewandt und versucht, mich zu töten... MICH!\n\nDas zeigt einmal mehr, dass einem Blutelfen nicht zu trauen ist.\n\nMein Problem ist: Sie haben immer noch meine Ausrüstung und ich kann sie nicht wiederbekommen. Helft Ihr mir?", sourceObjective = "Durchsucht den thalassischen Stützpunkt nach Kim'jaels Kompass, Zielfernrohr, ausgestopftem Huhn und Knobelwizz und bringt ihm dann alles nach Azshara zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[3602] = { id = 3602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsharit", description = "Die uralten Klippenriesen aus dem südlichen Azshara ernähren sich von Felsen und Gebäuden des Landes. Ihre Ausscheidung ist, bedingt durch die Ernährung, ein höchst formbarer und extrem starker Kristall, der als Azsharit bekannt ist.\n\nDer südliche Bogen ist übersät mit diesen Gebilden, aber es konnten nur wenige geborgen werden, da die Riesen über ein extrem angriffslustiges Naturell verfügen.\n\nIhr sollt nach Süden vorstoßen und genügend Azsharit einsammeln, um den Waffenkörper herzustellen. Meine Teufelshunde werden Euch beim Einsammeln der Kristalle behilflich sein.", sourceObjective = "Sammelt 20 kristallisierte Azsharite im südlichen Azshara. Ihr könnt den Teufelshund benutzen, damit er Euch beim 'Erschnüffeln' der gut versteckten Ablagerungen behilflich ist.\n\nKehrt zu Loramus zurück, sobald Ihr die Aufgabe erfüllt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3621] = { id = 3621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herstellung von Teufelsbann", description = "Die Waffen können jetzt geschmiedet werden. Ihr müsst den ausgehärteten Azsharit zu jemandem bringen, der die Fähigkeit besitzt, Teufelsenergie zu bändigen.\n\nIm Schlingendorntal gibt es einen solchen Schmied. Galvan der Alte, Anführer des Mithrilordens, wird die Waffen nach Euren Angaben fertigen. Ihr könnt sein Lager zwischen Zul'Gurub und dem Ogerhügel der Mosh'Ogg finden.\n\nMögen Eure Entschlossenheit und Euer Glaube Euch durch diese Tortur leiten. Solltet Ihr versagen, wisset, dass Euer Gott auf Euch herablächelt, sterbliches Wesen.", sourceObjective = "Bringt die Lieferung zu Galvan dem Alten im Schlingendorntal.", sourceObjectiveStatus = "unverified-source-field" }
quests[3625] = { id = 3625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzauberte Azsharitteufelswaffe", description = "{name}, die Herstellung jeder einzelnen Waffe wird einige Zeit in Anspruch nehmen.\n\nAußerdem dürft Ihr die Macht des Teufelsfluchs nur einmal alle drei Minuten verwenden. Seine schwächenden Eigenschaften gegen Razelikh den Entweiher und seine Diener können unterschiedlich lang dauern. Aus diesem Grund dürft Ihr den Teufelsfluch erst dann freigeben, wenn der richtige Zeitpunkt gekommen ist!\n\nGebt mir jetzt einen Moment, damit ich Eure Waffen fertigen kann, {name}.", sourceObjective = "Wartet, bis Galvan die Waffen fertig geschmiedet hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[3626] = { id = 3626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr in die Verwüsteten Lande", description = "Die Stunde der Erlösung rückt näher, {name}. Ihr müsst mit Eurer neuen Waffe in die Verwüsteten Lande zurückkehren und mit dem Gefallenen Helden der Horde sprechen, um Eure letzte Aufgabe zu erhalten.", sourceObjective = "Kehrt zum Gefallenen Helden der Horde zurück. Zu finden ist er an der Splitterspeerkreuzung in den Sümpfen des Elends.", sourceObjectiveStatus = "unverified-source-field" }
quests[3627] = { id = 3627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das zerbrochene Amulett vereinen", description = "Um den Entweiher zu erreichen, müsst Ihr zunächst das Dreigestirn der Macht zerstören und die Teile des Amuletts beschaffen. Wenn Ihr alle drei Teile beschafft habt, kommt zu mir zurück, und ich werde Euch weitere Anweisungen geben.\n\nGeht, {name}! Auf in die Verwüsteten Lande! Sevine, Allistarj und Grol müssen fallen!", sourceObjective = "Tötet Grol den Zerstörer, Lady Sevine und Erzmagier Allistarj. Nehmt das Amulett von Grol, das Amulett von Sevine und das Amulett von Allistarj von ihren Leichen.\n\nDenkt daran, Eure Verzauberte Azsharitteufelswaffe zu BENUTZEN, um die Triade zu schwächen. Auf eine andere Weise können sie nicht getötet werden - aber verwendet sie weise...", sourceObjectiveStatus = "unverified-source-field" }
quests[3628] = { id = 3628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr seid Rakh'likh, Dämon", description = "Razelikhs Unterschlupf befindet sich auf dem Gipfel des höchsten Berges in den Verwüsteten Landen. Einzig durch Einsatz der Teleport-Runen in der Nähe des Berges kann man zu diesem Unterschlupf gelangen. Solange Ihr das Amulett habt, könnt Ihr den Unterschlupf erreichen. Nachdem Ihr erst den Unterschlupf erreicht habt, müsst Ihr die Bestie herbeizaubern. Das Amulett ist Euer Schlüssel, {name}. Benutzt es auf dem Altar des Entweihers.\n\nFalls Ihr den Entweiher besiegen könnt, bringt sein Horn zurück. Es wird ein Symbol der Hoffnung für alle sein, die es sehen, ein Beweis dafür, dass es tatsächlich Helden in dieser vom Krieg zerrissenen Welt gibt.", sourceObjective = "Vernichtet Razelikh den Entweiher und bringt das abgespaltene Horn des Entweihers zum Gefallenen Helden der Horde. Ihr müsst außerdem den Zauberschutz des Entweihers mit zurückbringen, damit der Gefallene Held ihn zerstören und somit verhindern kann, dass er jemals in die falschen Hände fällt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3629] = { id = 3629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gobliningenieurskunst", description = "Experteningenieurskunst beinhaltet zwei unterschiedliche Disziplinen: für Gnome und für Goblins. Ich erwähne Gobliningenieurskunst nur, weil ich ein gerechter Lehrer bin. Sie machen gern Dinge, die in die Luft gehen und es ist ihnen dabei meistens egal, ob was im Weg herumsteht - auch wenn sie es selbst sind.\n\n{name}, lest diese Anleitung. Wenn Ihr lernen wollt, Euch selbst in die Luft zu jagen, dann bringt sie zu Nixx Sprossfeder nach Gadgetzan. Denkt daran - das ist eine dauerhafte Mitgliedschaft, es ist nicht möglich, in die andere Disziplin einzutreten, also solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", sourceObjective = "Wenn Ihr etwas über die Gobliningenieurskunst erlernen wollt, dann bringt das Handbuch der Ingenieurskunstdisziplinen zu Nixx Sprossfeder nach Gadgetzan.", sourceObjectiveStatus = "unverified-source-field" }
quests[3630] = { id = 3630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomeningenieurskunst", description = "Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen auf: für Gnome und für Goblins. Gnomeningenieurskunst ist die weit Überlegenere der beiden! Es geht um die Konstruktion von wunderbaren Apparaten und Geräten, die das Leben schöner machen.\n\n{name}, lest diese Anleitung. Wenn Ihr mehr über Gnomeningenieurskunst lernen wollt, dann bringt sie zu Tüftlermeister Oberfunks in Eisenschmiede. Denkt daran - das ist eine dauerhafte Mitgliedschaft und es ist nicht möglich, in die andere Disziplin einzutreten, also solltet Ihr Euch absolut sicher sein, dass Ihr Euch sicher seid, bevor Ihr seine Aufgabe ausführt.", sourceObjective = "Wenn Ihr etwas über die Gnomeningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Tüftlermeister Oberfunks nach Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[3631] = { id = 3631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsross beschwören", description = "Hmpf. Ich sage, Ihr seid nicht vorbereitet, aber das ist nicht meine Entscheidung. Strahad empfindet das anders und es ist seine Entscheidung... dieses Mal.\n\nEr wünscht mit Euch zu sprechen, und das schnell. Ihr werdet ihn immer noch über Ratschet im Brachland finden, in seinem kleinen Turm dort, mit seinen Akolythen.\n\nTrödelt nicht herum.", sourceObjective = "Sprecht mit Strahad Farsan im Brachland.", sourceObjectiveStatus = "unverified-source-field" }
quests[3632] = { id = 3632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomeningenieurskunst", description = "Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen auf: Gnom und Goblin. Gnomeningenieurskunst ist die weit Überlegenere der beiden! Es geht um die Konstruktion von wunderbaren Apparaten und Geräten, die das Leben schöner machen.\n\n{name}, lest diese Anleitung. Wenn Ihr mehr über Gnomeningenieurskunst lernen wollt, dann bringt sie zu Tüftlermeister Oberfunks hier in Eisenschmiede. Denkt daran - das ist eine dauerhafte Mitgliedschaft und es ist nicht möglich, in die andere Disziplin einzutreten, also solltet Ihr Euch absolut sicher sein, dass Ihr Euch sicher seid, bevor Ihr seine Aufgabe ausführt.", sourceObjective = "Wenn Ihr etwas über die Gnomeningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Tüftlermeister Oberfunks nach Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[3633] = { id = 3633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gobliningenieurskunst", description = "Bei der Experteningenieurskunst gibt es zwei unterschiedliche Disziplinen: Gnom und Goblin. Natürlich ist die Gobliningenieurskunst die Wahl aller brillanten Ingenieure. Durch den klugen Einsatz von hochempfindlichen Sprengstoffen und phantastischen Ausrüstungsgegenständen lernt Ihr, die Welt zu meistern!\n\n{name}, lest diese Anleitung. Wenn Ihr etwas über Gobliningenieurskunst wissen wollt, dann bringt sie zu Nixx Sprossfeder nach Gadgetzan. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", sourceObjective = "Wenn Ihr etwas über die Gobliningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Nixx Sprossfeder nach Gadgetzan in Tanaris.", sourceObjectiveStatus = "unverified-source-field" }
quests[3634] = { id = 3634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomeningenieurskunst", description = "Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen auf: für Gnome und für Goblins. Ich bin zwar der Meinung, dass es Verschwendung ist, aber Ihr solltet doch etwas über die Gnomenspezialisierung wissen. Sie machen Geräte und Apparate, die angeblich die Welt verändern, aber meistens gar nicht funktionieren.\n\n{name}, lest diese Anleitung. Wenn Ihr lernen wollt, wie man Briefbeschwerer aus Metall herstellt, dann bringt sie zu Tüftlermeister Oberfunks in Eisenschmiede. Denkt daran - das ist eine dauerhafte Mitgliedschaft und es ist nicht möglich, in die andere Disziplin einzutreten, also solltet Ihr Euch absolut sicher sein, dass Ihr Euch sicher seid, bevor Ihr seine Aufgabe ausführt.", sourceObjective = "Wenn Ihr etwas über die Gnomeningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Tüftlermeister Oberfunks nach Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[3635] = { id = 3635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomeningenieurskunst", description = "Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen: Gnom und Goblin. Ich bin zwar der Meinung, dass es reine Verschwendung ist, aber Ihr solltet doch etwas über die Spezialisierung der Gnome wissen. Sie machen Gegenstände und Apparate, die angeblich die Welt verändern, aber meistens gar nicht funktionieren.\n\n{name}, lest diese Anleitung. Wenn Ihr lernen wollt, wie man Briefbeschwerer aus Metall herstellt, dann bringt sie zu Glotz Widrikus in Beutebucht. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", sourceObjective = "Wenn Ihr mehr über die Gnomeningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Glotz Widrikus nach Beutebucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[3636] = { id = 3636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Licht bringen", description = "Die Geißel ist eine dauerhafte Bedrohung für die Allianz. Ich bin sicher, Euch ist diese Tatsache vertraut. Kürzlich erst stießen wir auf einige sehr seltsame Funde, {name}.\n\nIm Brachland gibt es ein fürchterliches Dickicht von Dornsträuchern, das Hügel der Klingenhauer heißt. Früher war es die Heimat von einfachen Stachelebern, aber nun ist offensichtlich, dass ein Pakt mit der Geißel geschlossen wurde, die viel schlimmere Kreaturen hervorbrachte... Sie werden jetzt von dem Lich, Amnennar dem Kältebringer, beherrscht.\n\nStellt Euch auf die Seite des Lichts, {name}, und macht diesem bösen Verbund ein Ende.", sourceObjective = "Erzbischof Benedictus will, dass Ihr Amnennar den Kältebringer in den Hügeln der Klingenhauer tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[3637] = { id = 3637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomeningenieurskunst", description = "Ingenieurskunst auf Expertenniveau gliedert sich in zwei Disziplinen: Gnom und Goblin. Ich bin zwar der Meinung, dass es reine Verschwendung ist, aber Ihr solltet doch etwas über die Spezialisierung der Gnome wissen. Sie machen Gegenstände und Apparate, die angeblich die Welt verändern, aber meistens gar nicht funktionieren.\n\n{name}, lest diese Anleitung. Wenn Ihr lernen wollt, wie man Briefbeschwerer aus Metall herstellt, dann bringt sie zu Glotz Widrikus in Beutebucht. Denkt daran - das ist eine dauerhafte Mitgliedschaft. Es ist also nicht möglich, auch in die andere Disziplin einzutreten, daher solltet Ihr genau wissen, was Ihr wollt, bevor Ihr seine Aufgabe ausführt.", sourceObjective = "Wenn Ihr mehr über die Gnomeningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Glotz Widrikus nach Beutebucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[3638] = { id = 3638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwur der Geheimhaltung", description = "Bei der Gobliningenieurskunst geht es um praktische Anwendungen mit hohem Profit und noch höherer Explosionskraft! Unsere Baupläne ermöglichen uns, mächtige Bomben und gewaltige Waffen hervorzubringen. Die Anleitung, die Ihr gelesen habt, berichtet darüber.\n\nDie Anleitung erwähnt auch unser uraltes Gelöbnis der Geheimhaltung unserer Baupläne. Sobald Ihr ein Gobliningenieur geworden seid, war's das. Es gibt keinerlei Zugang zur Gnomeningenieurskunst.\n\nWenn Ihr immer noch ein Gobliningenieur werden wollt, dann unterzeichnet dieses Dokument, mit dem Ihr eine lebenslange Geheimhaltung gelobt, und sprecht dann wieder mit mir. Denkt gut darüber nach, {name}.", sourceObjective = "Wenn Ihr ein Gobliningenieur werden wollt, dann müsst Ihr auf den Schwur der Geheimhaltung rechtsklicken und erneut mit Nixx Sprossfeder in Gadgetzan sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3639] = { id = 3639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeigt Eure Arbeit", description = "Das Glitzern in Euren Augen verrät Euch: Ihr wollt Dinge in die Luft jagen. In Euch steckt Talent, {name}, doch hätte ich gerne ein paar Proben Eurer Arbeit, um zu sehen, ob ich nicht Wege finden kann, goblinorientierte Techniken zu unterstreichen. Ich bräuchte Folgendes: zwanzig große Eisenbomben, zwanzig robuste Dynamitstangen und fünf explosive Schafe - und immer schön an die Sicherheit denken!\n\nBringt mir diese Gegenstände und Ihr seid ein offizieller Gobliningenieur!Ihr erlernt:", sourceObjective = "Bringt 20 große Eisenbomben, 20 robuste Dynamitstangen und 5 explosive Schafe zu Nixx Sprossfeder nach Gadgetzan.", sourceObjectiveStatus = "unverified-source-field" }
quests[3640] = { id = 3640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwur der Geheimhaltung", description = "Die Gnomeningenieurskunst beruht auf der Ingenieurskunsttheorie, die besagt, dass sie unseren Bedürfnissen zu dienen hat! Unsere Baupläne ermöglichen uns, Geräte hervorzubringen, die die Welt um uns kontrollieren. Die Anleitung, die Ihr gelesen habt, berichtet darüber.\n\nDie Anleitung erwähnt auch unser uraltes Gelöbnis der Geheimhaltung unserer Baupläne. Sobald Ihr ein Gnomeningenieur geworden seid, war's das. Es gibt keinerlei Zugang zur Gobliningenieurskunst.\n\nWenn Ihr immer noch ein Gnomeningenieur werden wollt, dann unterzeichnet dieses Dokument, mit dem Ihr eine lebenslange Geheimhaltung gelobt, und sprecht dann wieder mit mir. Denkt gut darüber nach, {name}.", sourceObjective = "Wenn Ihr ein Gnomeningenieur werden wollt, dann müsst Ihr auf den Schwur der Geheimhaltung rechtsklicken und erneut mit Tüftlermeister Oberfunks in Eisenschmiede sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3641] = { id = 3641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeigt Eure Arbeit", description = "Wenn Ihr bereit seid, ein paar RICHTIG tolle Dinge herzustellen, dann seid Ihr hier am richtigen Ort. Ich kann sehen, dass Ihr ein fähiger Ingenieur seid, doch möchte ich trotzdem ein paar Proben Eurer Arbeit. Was ich mir davon erhoffe, ist, Euer Können auf Wege zu analysieren die gnomenorientierten Techniken in Zukunft noch zu unterstreichen. Ich bräuchte die folgenden Proben: sechs Mithrilrohre, ein genaues Zielfernrohr und zwei hochentwickelte Zielattrappen.\n\nBringt mir diese Gegenstände und Ihr seid ein offizieller Gnomeningenieur mit Zugriff auf alle Baupläne!Ihr erlernt:", sourceObjective = "Bringt 6 Mithrilrohre, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen zu Tüftlermeister Oberfunks in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[3642] = { id = 3642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwur der Geheimhaltung", description = "Die Gnomeningenieurskunst beruht auf der Ingenieurskunsttheorie, die besagt, dass sie unseren Bedürfnissen zu dienen hat! Unsere Baupläne ermöglichen uns, Geräte hervorzubringen, die die Welt um uns kontrollieren. Die Anleitung, die Ihr gelesen habt, berichtet darüber.\n\nDie Anleitung erwähnt auch unser uraltes Gelöbnis der Geheimhaltung unserer Baupläne. Sobald Ihr ein Gnomeningenieur geworden seid, war's das. Es gibt keinerlei Zugang zur Gobliningenieurskunst.\n\nWenn Ihr immer noch ein Gnomeningenieur werden wollt, dann unterzeichnet dieses Dokument, mit dem Ihr eine lebenslange Geheimhaltung gelobt und sprecht dann wieder mit mir. Denkt gut darüber nach, {name}.", sourceObjective = "Wenn Ihr ein Gnomeningenieur werden wollt, dann müsst Ihr auf den Schwur der Geheimhaltung rechtsklicken und erneut mit Glotz Widrikus in Beutebucht sprechen.", sourceObjectiveStatus = "unverified-source-field" }
