quests[3661] = { id = 3661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Lieblinge?", description = "Wildekin sind unberechenbare Kreaturen, {name}. Sie sind zu einer außerordentlichen Zärtlichkeit fähig, aber diese Kreaturen können auch eine enorme Wildheit an den Tag legen, wenn etwas für sie sehr Wichtiges bedroht wird.\n\nDiese Kreaturen wurden angeblich von Elune geschaffen und ich bin daran interessiert herauszufinden, ob dies wirklich der Wahrheit entspricht.\n\nVor Kurzem habe ich etwas von einer Population von Wildekin gehört, die im Hinterland leben - heimtückische, primitive und wilde Eulenbestien. Man findet sie unter den wild lebenden Tieren dort. Würdet Ihr einige Wildekinfedern für mich sammeln?", sourceObjective = "Sammelt 15 Wildekinfedern aus dem Hinterland für Erelas Himmelsbern in Rut'theran.", sourceObjectiveStatus = "unverified-source-field" }
quests[3681] = { id = 3681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foliant der Offenbarung", description = "Verzeiht, dass wir Eure Reise unterbrechen, {race}, aber ich dachte, Ihr solltet wissen, dass uns vor Kurzem eine Meldung aus Sturmwind erreicht hat, dass sich Paladine zum Training dort melden sollen.\n\nWenn ich es nicht besser wüsste, würde ich sagen, dass bald etwas Besonderes geschehen wird und es für Euch an der Zeit ist, die Folianten zu studieren.\n\nSucht Duthorian Rall in Sturmwind auf. Er trainiert für gewöhnlich Paladine in der Kathedrale des Lichts.", sourceObjective = "Sprecht mit Duthorian Rall in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[3701] = { id = 3701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die glimmenden Ruinen von Thaurissan", description = "Begebt Euch zu den glimmenden Ruinen von Thaurissan in der Brennenden Steppe und sammelt so viele Informationen wie möglich.\n\nEs heißt, dass geheimnisvolle Relikte in den Ruinen verstreut seien. Vielleicht solltet Ihr Eure Suche dort beginnen, {name}. Nehmt Euch vor den thaurissanischen Wächtern in Acht: Es sind Auftragsmörder, die die Ruinen bewachen und die dort möglicherweise noch immer begrabenen Geheimnisse beschützen, wie auch immer sie aussehen mögen.", sourceObjective = "Begebt Euch zu den Ruinen von Thaurissan in der Brennenden Steppe und sammelt Informationen über die Relikte von Thaurissan. Kehrt zur königlichen Historikerin Archesonus zurück, wenn Ihr die Informationen besorgt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[3702] = { id = 3702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die glimmenden Ruinen von Thaurissan", description = "Würdet Ihr gern einen Überblick über die Geschichte der Dunkeleisenzwerge erhalten?", sourceObjective = "Hört die Erzählung der königlichen Historikerin Archesonus über die Geschichte von Thaurissan.", sourceObjectiveStatus = "unverified-source-field" }
quests[3721] = { id = 3721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein eigener OOX", sourceObjective = "Ihr habt drei meiner OOX-Leitroboter gefunden! Ihr habt viel mehr als das getan, worum ich Euch gebeten hatte. Daher will ich Euch etwas Besonderes für Eure Hilfe geben. Dies ist eine Miniaturversion jenes Roboters, den Ihr jetzt kennt und liebt, den OOX!\n\nIch würde normalerweise niemandem solch ein potenziell tödliches Gerät anvertrauen, aber Ihr wart eine wirklich große Hilfe. Außerdem wurden die Kampfmechanismen und die Leitlogik dieses Exemplars deaktiviert.\n\nAber abgesehen davon ist das ein echter OOX!", sourceObjectiveStatus = "unverified-source-field" }
quests[3741] = { id = 3741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilarys Halskette", description = "Meine Freundin Hilary hat ihre Halskette verloren und wir können sie einfach nicht finden. Den ganzen Tag lang fischen wir schon hier und haben auch schon rundum überall gesucht. Ich kann mir nur vorstellen, dass sie in den See gefallen ist. Unsere Eltern möchten nicht, dass wir im See schwimmen... meine Mama sagt, dass es unter Wasser ein paar garstige Dinge gibt, aber Ihr seht aus, als ob Ihr keine Angst vor garstigen Dingen hättet.\n\nKönnt Ihr die Kette bitte für uns suchen?", sourceObjective = "Sucht Hilarys Halskette und bringt sie Hilary in Seenhain zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[3761] = { id = 3761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erde von Un'Goro", description = "Die Erde des Kraters von Un'Goro ist angeblich reich an starken magischen Eigenschaften. Der Zirkel des Cenarius möchte diese Erde in großen Mengen untersuchen; zieht daher in die Wildnis von Un'Goro und sammelt genug davon für unsere ständig laufenden Forschungen.\n\nDie angereicherte Erde ist manchmal zu Haufen aufgeworfen und einige der Wildtiere könnten vielleicht nützliche Proben bei sich haben. Bringt sie raus zu Ghede; sucht einfach nach den Erdhaufen und dem Tauren, der Befehle brüllt. Er ist kein schlechter Kerl, aber verärgert ihn lieber nicht!", sourceObjective = "Bringt 20 Erdproben von Un'Goro zu Ghede in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[3762] = { id = 3762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzdruide Runentotem helfen", description = "Entschuldigung, {class}, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Donnerfels ist sehr an erfahrenen Abenteurern wie Euch interessiert, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein Geringerer als Hamuul Runentotem an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm auf der Anhöhe der Ältesten in Donnerfels.", sourceObjective = "Sprecht in Donnerfels mit Erzdruide Hamuul Runentotem.", sourceObjectiveStatus = "unverified-source-field" }
quests[3763] = { id = 3763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzdruide Hirschhaupt helfen", description = "Entschuldigung, {class}, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Darnassus sucht nach erfahrenen Abenteurern wie Euch, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein geringerer als Erzdruide Fandral Hirschhaupt an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm in der Enklave des Cenarius in Darnassus.", sourceObjective = "Sprecht mit Erzdruide Fandral Hirschhaupt in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[3764] = { id = 3764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erde von Un'Goro", description = "Die Erde des Kraters von Un'Goro ist angeblich reich an starken magischen Eigenschaften. Ich möchte Wahrheit von Unwahrheit unterscheiden; begebt Euch daher in die Wildnis von Un'Goro und sammelt ausreichend hochwertige Erdproben für unsere ständig laufenden Studien.\n\nIhr glaubt möglicherweise, dass die Aufgabe, etwas zu sammeln, unter Eurer Würde sei; doch mit solch einer Einstellung macht Ihr Euch weder bei mir noch beim Zirkel des Cenarius beliebt. Bringt die Proben zu Jenal, der zweifellos draußen hinter diesem Baum müßig herumlungert; sucht einfach nach den Erdhaufen. Er wird sich um die Logistik kümmern, nicht ich.", sourceObjective = "Bringt 20 Erdproben von Un'Goro zu Jenal in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[3765] = { id = 3765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnis in der Fremde", description = "Sturmwind - geschäftiger Dreh- und Angelpunkt der Aktivität.\n\nIch bin weit gereist, um Hilfe zu suchen. Man hört häufig, dass mutige Abenteurer durch die Straßen dieser Stadt ziehen.\n\nMein Bruder Gershala benötigt Hilfe in Dunkelküste. Er lebt in der Küstenstadt Auberdine.\n\nDie Reise ist lang und abenteuerlich. Daher suche ich nach Hilfe. Es sollte <ein erfahrener/eine erfahrene:c> {class} sein, so wie Ihr.", sourceObjective = "Reist zu Gershala Nachtraunen in Auberdine.", sourceObjectiveStatus = "unverified-source-field" }
quests[3781] = { id = 3781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgenkornforschung", description = "Mit dem, was wir einen Immergrünbeutel nennen, haben wir Tharlendrissamenkörner in der Erde des Kraters von Un'Goro kultiviert. Diese Samenkörner sind zu einer Ansammlung wirksamer Kräuter erblüht. Ein Ergebnis ist das Morgenkorn, ein rätselhaftes Kraut, von dem wir wenig wissen; ich habe vor, dieses Geheimnis zu enthüllen.\n\nBringt das nach unten zu Mathrengyl, und er wird Euch einige Samenkörner geben, mit denen Ihr beginnen könnt. Wenn Ihr diese verbraucht habt, müsst Ihr weitere von ihm kaufen.", sourceObjective = "Bringt den Samenkorngutschein des Erzdruiden zu Mathrengyl Bärenfährte in der Enklave des Cenarius von Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[3782] = { id = 3782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgenkornforschung", description = "Mit dem, was wir einen Immergrünbeutel nennen, haben wir Tharlendrissamenkörner in der Erde des Kraters von Un'Goro kultiviert. Diese Samenkörner sind zu einer Ansammlung wirksamer Kräuter erblüht. Ein Ergebnis ist das Morgenkorn, ein rätselhaftes Kraut, von dem wir wenig wissen; ich hoffe, dieses Geheimnis für den Zirkel zu enthüllen.\n\nBringt diesen Gutschein zu meiner Tochter Bashana, und sie wird Euch einige Samenkörner geben, damit Ihr uns helfen könnt. Wenn Ihr diese verbraucht habt, müsst Ihr weitere von ihr kaufen.", sourceObjective = "Bringt den Samenkorngutschein zu Bashana Runentotem in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[3783] = { id = 3783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sind wir endlich da, Yeti?", description = "Meine Freunde hatten immerzu tolle Ideen. Ich hatte nie das Gefühl mit ihnen mithalten zu können... bis heute! Gerade habe ich die Pläne für etwas Großes angefertigt! Wenn Ihr versprecht, es nicht zu erzählen, weihe ich Euch in das Geheimnis ein... \n\nIch werde einen mechanischen Yeti herstellen! Meine Freunde werden ganz bestimmt durchdrehen, wenn sie ihn sehen, aber wenn sie darüber hinweg sind, bin ich mir sicher, dass sie beeindruckt sein werden!\n\nFür den Anfang benötige ich dickes Yetifell von Eisdistelyetis. Werdet Ihr helfen? Ihr könnt sie im Südosten finden.", sourceObjective = "Sammelt 10 dicke Yetifelle für Umi Rumpelkicher in der Ewigen Warte.", sourceObjectiveStatus = "unverified-source-field" }
quests[3784] = { id = 3784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzdruide Runentotem helfen", description = "Entschuldigung, {class}, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Donnerfels ist sehr an erfahrenen Abenteurern wie Euch interessiert, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein Geringerer als Hamuul Runentotem an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm auf der Anhöhe der Ältesten in Donnerfels.", sourceObjective = "Sprecht in Donnerfels mit Erzdruide Hamuul Runentotem.", sourceObjectiveStatus = "unverified-source-field" }
quests[3785] = { id = 3785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgenkornforschung", description = "Hier ist Euer Immergrünbeutel, den Ihr für die Nutzung der Tharlendrissamenkörner benötigen werdet. Ihr benötigt außerdem noch Erdproben von Un'Goro als Dünger für die Samenkörner. Verwendet einfach den Beutel, wenn Ihr alles habt; der Beutel wird den Rest erledigen.\n\nWenn Ihr genug Einheiten Morgenkorn habt, bringt sie mir hierher in die Enklave. Und belästigt bitte nicht den Erzdruiden; er ist ein sehr beschäftigter Mann und muss nicht jedes Mal gestört werden, wenn jemand mit einer Ladung Morgenkorn zurückkehrt!", sourceObjective = "Benutzt einen Immergrünbeutel mit einem Paket Tharlendrissamenkörner sowie zwei Erdproben von Un'Goro, um Morgenkorn zu kultivieren.\n\nBringt 10 Einheiten Morgenkorn zu Mathrengyl Bärenfährte in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[3786] = { id = 3786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgenkornforschung", description = "Hier ist Euer Immergrünbeutel, den Ihr für die Nutzung der Tharlendrissamenkörner benötigen werdet. Ihr benötigt außerdem noch Erdproben von Un'Goro als Dünger für die Samenkörner. Verwendet einfach den Beutel, wenn Ihr alles habt; der Beutel wird den Rest erledigen.\n\nWenn Ihr genug Einheiten Morgenkorn habt, bringt sie zu mir hierher auf die Anhöhe der Ältesten. Belästigt bitte nicht den Erzdruiden; er wird sehr mit den Forschungsarbeiten beschäftigt sein sowie mit den tausend anderen Sorgen, die er hat!", sourceObjective = "Benutzt einen Immergrünbeutel mit einem Paket Tharlendrissamenkörner sowie zwei Erdproben von Un'Goro, um Morgenkorn zu kultivieren.\n\nBringt 10 Einheiten Morgenkorn zu Bashana Runentotem in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[3787] = { id = 3787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebenshands Bitte", description = "Entschuldigung...\n\nEin Kollege von mir würde gern mit Euch über die Forschungsarbeiten sprechen, die Ihr zusammen mit dem Zirkel des Cenarius durchführt. Er ist ein Druide namens Quintis Lebenshand und lebt in der Mondfederfeste in Feralas. Er würde gern mit Euch über Morgenkorn reden... und er würde es vorziehen, wenn unser Gespräch dem Erzdruiden nicht zu Ohren kommt.\n\nFalls Ihr interessiert seid, dann sprecht mit ihm; zweifellos wird alles klargelegt, wenn Ihr es tut.", sourceObjective = "Sprecht mit Quintis Lebenshand in der Mondfederfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[3788] = { id = 3788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lebenshands Bitte", description = "Entschuldigung...\n\nEin Kollege von mir würde gern mit Euch über die Forschungsarbeiten sprechen, die Ihr zusammen mit dem Zirkel des Cenarius durchführt. Er ist ein Druide namens Quintis Lebenshand und lebt hier in der Mondfederfeste. Er würde gern mit Euch über Morgenkorn reden... und er würde es vorziehen, wenn unser Gespräch dem Erzdruiden nicht zu Ohren kommt.\n\nFalls Ihr interessiert seid, dann sprecht mit ihm; zweifellos wird alles klargelegt, wenn Ihr es tut.", sourceObjective = "Sprecht mit Quintis Lebenshand in der Mondfederfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[3789] = { id = 3789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzdruide Hirschhaupt helfen", description = "Entschuldigung, {class}, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Darnassus sucht nach erfahrenen Abenteurern wie Euch, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein geringerer als Erzdruide Fandral Hirschhaupt an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm in der Enklave des Cenarius in Darnassus.", sourceObjective = "Sprecht mit Erzdruide Fandral Hirschhaupt in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[3790] = { id = 3790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzdruide Hirschhaupt helfen", description = "Entschuldigung, {class}, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Darnassus sucht nach erfahrenen Abenteurern wie Euch, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein geringerer als Erzdruide Fandral Hirschhaupt an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm in der Enklave des Cenarius in Darnassus.", sourceObjective = "Sprecht mit Erzdruide Fandral Hirschhaupt in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[3791] = { id = 3791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geheimnis des Morgenkorns", description = "Lasst mich offen mit Euch sein, {name}. Ich bin interessiert zu wissen - nein, ich muss es unbedingt wissen, warum der Erzdruide in Darnassus den Namen des Zirkels des Cenarius sowie dessen Mittel benutzt, um große Mengen Morgenkorn zu beschaffen. Ich bin ein Forscher - Flüche sind meine Spezialität. Ich habe gehört, dass Morgenkorn unter den richtigen Bedingungen Fähigkeiten verströmt wie andere Kräuter, die in primitiven Flüchen eingesetzt werden.\n\nIch möchte mehr darüber wissen und bitte Euch um Eure Hilfe. Bringt mir 10 Einheiten Morgenkorn und ich werde mich um Euch kümmern.", sourceObjective = "Bringt 10 Einheiten Morgenkorn zu Quintis Lebenshand in der Mondfederfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[3792] = { id = 3792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgenkorn für die Mondfederfeste" }
quests[3801] = { id = 3801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkeleisenerbe", description = "Seid gegrüßt, {name}. Ich bin Franclorn Schmiedevater. Ja, der Franclorn Schmiedevater, der für die Steinwerkmethode der Architektur verantwortlich ist. Ihr habt zweifellos während Eurer Abenteuer in unserer vom Krieg zerrissenen Welt eines meiner Werke durchquert oder habt auf einem gestanden.\n\nIhr fragt Euch wahrscheinlich, warum ich hier bin und was ich von Euch möchte - beides berechtigte Fragen.\n\nIch brauche natürlich Eure Hilfe. Im Austausch für Eure Hilfe gewähre ich Euch den Schlüssel zu den Tiefen meiner verfluchten Stadt.", sourceObjective = "Sprecht mit Franclorn Schmiedevater bei Schmiedevaters Grabmal im Schwarzfels, wenn Ihr daran interessiert seid, einen Schlüssel für die Hauptstadt zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[3802] = { id = 3802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkeleisenerbe", description = "Ihr findet Fineous Dunkelader jenseits des Rings des Gesetzes in der Halle des Handwerks. Tötet den elenden Wicht und nehmt Eisenhölle an Euch.\n\nBringt Eisenhölle zum Schrein von Thaurissan und legt den Hammer an seinen rechtmäßigen Ort: in die Hände der Statue, die mir zu Ehren aufgestellt wurde.\n\nSobald dieses getan ist, öffnet sich das Fach, in dem ich den Hauptschlüssel verborgen habe. Wichtiger jedoch ist: Eisenhölle wird für alle Zeiten in meinen Händen bleiben. Sollte jemand versuchen, den Hammer zu entfernen, werden Statue und Hammer bersten und für immer verloren sein.", sourceObjective = "Erschlagt Fineous Dunkelader und bergt den großen Hammer Eisenhölle. Bringt Eisenhölle zum Schrein von Thaurissan und legt ihn auf die Statue von Franclorn Schmiedevater.", sourceObjectiveStatus = "unverified-source-field" }
quests[3803] = { id = 3803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgenkorn nach Darnassus" }
quests[3804] = { id = 3804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgenkorn nach Donnerfels" }
quests[3821] = { id = 3821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreckensfels", description = "Sha'ni wurde ausgeschickt, um Berichte über merkwürdige rituelle Aktivitäten zu untersuchen, die vor mehr als drei Wochen von den Feuermagenogern der Brennenden Steppe kamen.\n\nBluthauer sagt mir, dass er noch nichts wieder von dieser Gruppe gehört hätte und dass es am besten sei, wenn ich einfach weitermache und mich auf meine Aufgabe konzentriere. Könnt Ihr Euch das vorstellen? Das ist doch meine Frau!\n\nIch kann meinen Posten nicht verlassen, {name}, aber ich muss wissen, was aus Sha'ni geworden ist. Reist in die Brennende Steppe und sucht nach ihr.", sourceObjective = "Begebt Euch in die Brennende Steppe und findet heraus, was aus Sha'ni Ehrenhauer geworden ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[3822] = { id = 3822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krom'Grul", description = "Meine ganze Gruppe wurde gefangen genommen, {name}. Alle wurden getötet - alle, außer mir.\n\nIhr Anführer Krom'Grul wollte mich für irgendein Ritual aufsparen.\n\nIch wurde von dem Biest an diesen Altar gekettet und brutal misshandelt. Mein körperliches Sein gab nach einer Stunde dieser Folter auf. Die Bestie riss mir dann meinen Ehenasenring aus dem Gesicht und steckte ihn an seinen Finger. Noch niemals habe ich solch eine Rohheit gesehen!\n\nFindet Krom'Grul und erledigt ihn! Bringt meinen Ring zurück zu Thal'trak.\n\nUnd, {name}, sagt ihm, dass wir uns wiedersehen werden...in einem anderen Leben.", sourceObjective = "Holt Sha'nis Nasenring von Krom'Grul zurück und bringt ihn zu Thal'trak in Kargath. Durchsucht die verschiedenen Höhlen und Minen im Schreckensfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[3823] = { id = 3823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Feuermagenoger auslöschen", description = "Wir müssen unsere Feinde schlagen, bevor sie uns schlagen!\n\nIch werde es kurz machen, Soldat.\n\nDie Feuermagenoger der Brennenden Steppe sind Verbündete der Orcs des Schwarzfelsklans. Sie arbeiten eng mit diesen üblen Orcs zusammen, bewachen den mineralreichen Schreckensfels und halten die Nachschublinien ständig offen.\n\nHinterlasst Euer Zeichen, {name}. Legt ihre Streitkräfte lahm und kehrt zu mir zurück, wenn der Auftrag erledigt ist.\n\n<Oralius greift in die Luft und macht eine erwürgende Bewegung.>\n\nICH BRING DICH UM, WINKY!", sourceObjective = "Tötet 15 Ogermagier der Feuermägen, 7 Oger der Feuermägen sowie 7 Schläger der Feuermägen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3824] = { id = 3824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gor'tesh der Schläger-Lord", description = "Sie sind gelähmt, ich sag's Euch! Unser nächster Schlag muss entscheidend sein.\n\nDer Lord dieser Bestien, Gor'tesh, muss eliminiert werden. Wichtiger noch, sein Kopf muss zu mir zurückgebracht werden, damit ich die dritte Phase unseres Angriffs auf die Feuermagenoger vorbereiten kann.\n\nSeid gewarnt, Soldat, Gor'tesh regiert nicht vom Schreckensfelsen aus. Stattdessen befindet er sich in einem Gebäude der Schwarzfelsorcs westlich vom Schreckensfelsen.\n\nEure Befehle sind daher einfach. Sucht Gor'tesh und hackt ihm seinen fetten Kopf ab. Kommt zurück, wenn Eure Aufgabe erledigt ist.\n\nKLAPPE HALTEN, WINKY!", sourceObjective = "Beschafft Euch Gor'teshs abgehackten Kopf.", sourceObjectiveStatus = "unverified-source-field" }
quests[3825] = { id = 3825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogerkopf auf einem Pfahl = Party", description = "Jetzt müsst Ihr nur noch eine Sache erledigen, Soldat.\n\nIch habe mir die Freiheit genommen, Gor'teshs Kopf auf einen Pfahl zu stecken. Ihr sollt jetzt einfach diesen Kopf zur Spitze des Schreckensfelsens bringen und ihn in den Boden rammen. Wenn Ihr das getan habt, seht zu, wie diese feigen Oger um ihr Leben rennen! Nachdem Ihr Euren Spaß hattet, kommt zu mir zurück und ich werde Euch für all Eure harte Arbeit belohnen.\n\n<Oralius scheint seinen Bezug zur Realität zu verlieren.>", sourceObjective = "Nehmt Gor'teshs abgehackten Kopf und platziert ihn auf dem Gipfel des Schreckensfelsens. Sucht nach einem weichen Erdhügel, um den Pfahl aufzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3841] = { id = 3841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waise sucht Zuhause", description = "Ach, hallo, {name}. Ich freue mich sehr, Euch wiederzusehen. Wie war Eure Reise nach Darnassus?\n\nNa, Ihr seid bestimmt froh darüber, dass wir während Eurer Abwesenheit ziemliche Fortschritte gemacht haben. Wir haben sogar ein ganzes Nest voller Eier gerettet. Leider ist die Mutter gestorben, ehe wir sie gefunden haben.\n\nSagt mal, wollt Ihr nicht vielleicht so ein Tierchen haben? Es sieht aus, als würden sie bald schlüpfen, und dann brauchen sie <einen guten Vater/eine gute Mutter>. Was meint Ihr?\n\nWenn Ihr wirklich Interesse habt, dann bringt eines der Eier zu Quentin. Ihr findet ihn an der Rennbahn in der Schimmernden Ebene. Er kann Euch mehr darüber sagen.", sourceObjective = "Sprecht mit Quentin in Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[3842] = { id = 3842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurz vor dem Schlüpfen", description = "Die Mondwebers, wie? Überaus interessant. Schade, dass die Grimmlingflitzer nicht schätzen können, was es bedeutet, wenn diese beiden sich um sie kümmern. Beide sind überaus fähig und gut.\n\nSoso, sie haben Euch das Ei also geschenkt. Tja, dann solltet Ihr auch so lange dafür verantwortlich sein, wie Ihr dies wünscht. Das Junge scheint wohl schon bald zu schlüpfen, aber wir sollten trotzdem sichergehen, dass es gesund ist und keinen Schaden genommen hat.\n\nIch brauche lediglich zwei Elixiere der Seelenstärke für einen kleinen Zauber, der das Ei beschützen wird. Die übrigen Komponenten habe ich bereits hier.", sourceObjective = "Bringt 2 Elixiere der Seelenstärke zu Quentin in Tausend Nadeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[3843] = { id = 3843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das neueste Mitglied der Familie", description = "Ein prachtvolles Exemplar, {name}. Wenn dieses Geschöpf das Heranreifen übersteht, dann wird es ein wahrhaft gesundes Tier sein!\n\nAber eines würde ich Euch noch vorschlagen, wenn Ihr es damit wirklich ernst meint - geht zum Nistgipfel im Hinterland. Sprecht dort mit einem Zwerg namens Agnar Tiermeister. Er ist ein Tierführermeister und kann Euch bestimmt bei den letzten Stadien der Brutzeit behilflich sein.\n\nAber eilt Euch, {name}, das Ei ist empfindlich und wird sich ohne die richtige Pflege nicht lange halten.", sourceObjective = "Bringt Euer empfindliches Grimmlingflitzerei ins Hinterland und sprecht mit Agnar Tiermeister, aber beeilt Euch. Ihr habt nur eine Stunde Zeit, ihn zu finden. Dann stirbt das Jungtier in dem Ei.", sourceObjectiveStatus = "unverified-source-field" }
quests[3844] = { id = 3844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist für jeden ein Geheimnis", description = "In Ufernähe liegt ein zerstörtes Floß. Das hier ist nur ein kleiner Tümpel, deswegen ist Euch nicht so ganz klar, wie das Floß hier landen konnte. Aber ein Blick auf die Bäume verrät Euch, dass der Wasserstand im Teich nicht unbedingt immer derselbe sein muss.\n\nVielleicht findet Ihr ja mehr heraus, wenn Ihr Euch ein bisschen in der Gegend umschaut...", sourceObjective = "Sucht in dem Tümpel nach einem Hinweis darauf, wem dieses havarierte Floß gehören könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[3845] = { id = 3845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist für jeden ein Geheimnis", description = "Ihr greift nach dem Bündel und zieht es an Land. Vielleicht findet Ihr heraus, wem es gehört, wenn Ihr die Gegenstände darin untersucht.\n\nIn Marschalls Zuflucht halten sich ein paar vereinzelte Reisende auf. Vielleicht lässt sich dort ja mehr herausfinden.", sourceObjective = "Untersucht die Gegenstände in dem Bündel und bringt sie zu ihrem Besitzer.", sourceObjectiveStatus = "unverified-source-field" }
quests[3861] = { id = 3861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GLUCK!", description = "Gack... gack... gack... GAGGACK!\n\nGack... gack... gack.\n\nDas Huhn sieht zu Euch hinauf und beginnt dann, mit seinen Krallen am Boden zu scharren. Ihr glaubt, dass es ein Wort schreibt, aber Ihr seid Euch nicht sicher, was es ist. Könnte es das sein... S-A-L-D-E-A-N? Bevor Ihr fragen könnt, dreht sich das Huhn weg und geht seinem Geschäft nach.", sourceObjective = "Beschafft Euch etwas Spezialhühnerfutter und kehrt zu dem Huhn zurück, das sich mit Euch angefreundet hat. Wenn Ihr es gefunden habt, dann benutzt erst /jubeln, ehe Ihr dem Huhn das Spezialhühnerfutter gebt.", progress = "Das Huhn starrt Euch mit dunklen, kalten Augen an. Hungrig wartet es auf Euch.\n\n\"GAGGAAACK!\n\nGack... gack... gack.\"", completion = "GAGGACK!!!\n\nDas Huhn beginnt gierig, das Futter aufzupicken, das Ihr ihm hingestreut habt.\n\nNach einer kurzen Weile sieht es sich überrascht um. Dann trippelt es unruhig vor und zurück. Ob dieses Huhn vielleicht gleich ein Ei legt? Vielleicht solltet Ihr besser einmal darunter nachsehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[3881] = { id = 3881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettungsexpedition", description = "Ich weiß zwar nicht, wie Ihr es bis hierher geschafft habt, aber Ihr seid Balsam für meine Augen! Ich heiße Williden Marschall und bin der Leiter eines neutralen Expeditionstrupps. Unsere jüngste und größte Unternehmung wurde von zahllosen Katastrophen begleitet. Die schlimmste davon war, dass wir die Wildheit des Kraters von Un'Goro unterschätzt hatten.\n\nAls wir aus unseren Stützpunkten im südwestlichen und nordöstlichen Teil des Kraters flohen, ließen wir lebenswichtige Vorräte zurück. Ihr seht aus, als wärt Ihr recht stark und geschickt... Könnt Ihr uns vielleicht dabei helfen, sie zurückzubekommen?", sourceObjective = "Bringt eine Kiste mit Nahrungsmitteln und Forscherausrüstung zu Williden Marschall im Krater von Un'Goro.", sourceObjectiveStatus = "unverified-source-field" }
